// ==========================================
// ALBAYAN MANAGER - VANILLA JS COMPLETE
// Full-featured conversion from React
// SECURITY ENHANCED VERSION
// ==========================================

// ==========================================
// ALBAYAN PLATFORM (FUTURE PLAN + RULES)
// ==========================================
// This codebase is intended to evolve into a **multi-service platform** (web now, mobile later).
// New services must plug in cleanly without breaking existing ones (especially Albayan Manager).
//
// Core platform primitives (do NOT break these):
// - Services catalog: `SERVICES` + `SMART_SYSTEMS_CHILDREN` (config-driven, stable IDs)
// - Wallet: `walletTransactions` is an **immutable ledger** (balance is computed, not stored)
// - Subscriptions: `serviceSubscriptions` is the source of truth for service access
// - Server mode (FastAPI/Postgres): server is authoritative for multi-user internet usage
//
// Non‑negotiable rules for future edits (human + AI):
// 1) NEVER store wallet balance as a mutable field; only append ledger transactions.
// 2) NEVER allow editing/deleting `walletTransactions` or subscription history (use reversals/cancel records).
// 3) NEVER change a service `id` after launch (it becomes part of URLs, mobile deep links, subscriptions).
// 4) Any new “large” collection must be persisted in IndexedDB: add to `state` + `PERSISTED_COLLECTIONS`.
// 5) Keep services isolated; reuse platform modules instead of copy/paste logic across services.
// 6) No plaintext secrets (passwords, tokens, recovery keys). Keep audit logs redacted.
//
// Docs to read before major changes:
// - `PLATFORM_FOUNDATION.md` (architecture + portability)
// - `CONTRIBUTING.md` (how to extend safely)
// - `MONEY_PLATFORM_ROADMAP.md` (payments/POS/cards roadmap + money safety rules)
//
// ==========================================
// PLATFORM DETECTION MODULE
// ==========================================
// Detects platform (web, iOS, Android, HarmonyOS) and capabilities

// /studio (or a studio. subdomain) boots the standalone Ads Studio shell.
const IS_STUDIO_SHELL = (
  /^\/studio(\/|$)/.test(window.location.pathname || '')
  || /^studio\./i.test(window.location.hostname || '')
);

const Platform = {
  // Cache detection results for performance
  _cache: null,
  
  // Detect platform once and cache results
  detect: function() {
    if (this._cache) return this._cache;
    
    const ua = navigator.userAgent || '';
    const uaLower = ua.toLowerCase();
    
    // Check for Capacitor (mobile app). document.URL is read defensively:
    // headless test sandboxes stub document without it, and detect() is now
    // reachable from routing paths (browser Back/overlay history model).
    const docUrl = String((typeof document !== 'undefined' && document.URL) || '');
    const isCapacitor = typeof window.Capacitor !== 'undefined' ||
                        docUrl.startsWith('capacitor://') ||
                        docUrl.startsWith('ionic://');
    
    // Detect specific platform
    let platform = 'web';
    if (isCapacitor) {
      if (/iphone|ipad|ipod/i.test(ua)) {
        platform = 'ios';
      } else if (/android/i.test(ua)) {
        platform = 'android';
      } else if (/harmonyos/i.test(ua) || /huawei/i.test(ua)) {
        platform = 'harmony';
      } else {
        platform = 'capacitor-unknown';
      }
    }
    
    // Detect touch capability
    const isTouch = ('ontouchstart' in window) ||
                    (navigator.maxTouchPoints > 0) ||
                    (navigator.msMaxTouchPoints > 0);
    
    // Detect if hover is supported (CSS media query approach)
    const supportsHover = window.matchMedia('(hover: hover)').matches;
    
    // Detect mobile browser (not Capacitor but mobile browser)
    const isMobileBrowser = !isCapacitor && (
      /iphone|ipad|ipod|android|blackberry|windows phone/i.test(ua) ||
      (isTouch && window.innerWidth < 768)
    );

    // Detect in-app browsers (webviews embedded inside other apps). Users
    // arrive from Facebook ads, so the FB/IG/Messenger in-app browsers are a
    // primary environment — and they silently break blob downloads,
    // window.print() and target=_blank handoffs. Detection is deliberately
    // token-based (explicit app UA markers only): NO generic "iOS without a
    // Safari/ token" heuristic, because the installed PWA also drops the
    // Safari/ token and would be misclassified. Capacitor is excluded first:
    // its Android shell UA carries the same '; wv)' WebView marker.
    let isInAppBrowser = false;
    let inAppBrowserKind = null;
    if (!isCapacitor) {
      try {
        if (/FBAN|FBAV|FB_IAB|FBIOS/i.test(ua)) {
          // Facebook family. Messenger ships the same FB tokens plus its own
          // app names (MessengerForiOS / Orca-Android), so the sub-check is
          // safe — it only runs once an FB token already matched.
          isInAppBrowser = true;
          inAppBrowserKind = /messenger|orca/i.test(ua) ? 'messenger' : 'facebook';
        } else if (/instagram/i.test(ua)) {
          isInAppBrowser = true;
          inAppBrowserKind = 'instagram';
        } else if (/android/i.test(ua) && /; wv\)/.test(ua)) {
          // Stock Android WebView marker (Chrome's "; wv)" token) — covers
          // FB Lite, Gmail, and any other app hosting a bare WebView.
          isInAppBrowser = true;
          inAppBrowserKind = 'android-webview';
        } else if (/\bLine\/|MicroMessenger|Snapchat|TikTok|musical_ly|BytedanceWebview|\bGSA\//i.test(ua)) {
          // Other well-known in-app shells (LINE, WeChat, Snapchat, TikTok,
          // the Google app). Same degraded capabilities; no finer branding
          // is needed by any consumer.
          isInAppBrowser = true;
          inAppBrowserKind = 'other';
        }
      } catch (_) {
        // Never let UA sniffing break platform detection.
        isInAppBrowser = false;
        inAppBrowserKind = null;
      }
    }

    this._cache = {
      isCapacitor,
      platform,
      isTouch,
      supportsHover,
      isMobileBrowser,
      isInAppBrowser,
      inAppBrowserKind,
      isMobile: isCapacitor || isMobileBrowser,
      isWeb: !isCapacitor,
      isIOS: platform === 'ios',
      isAndroid: platform === 'android',
      isHarmony: platform === 'harmony',
      userAgent: ua
    };
    
    // Log platform detection for debugging
    console.log('[Platform] Detected:', this._cache);
    
    return this._cache;
  },
  
  // Convenience getters
  get isCapacitor() { return this.detect().isCapacitor; },
  get platform() { return this.detect().platform; },
  get isTouch() { return this.detect().isTouch; },
  get supportsHover() { return this.detect().supportsHover; },
  get isMobile() { return this.detect().isMobile; },
  get isMobileBrowser() { return this.detect().isMobileBrowser; },
  // In-app webview shells (Facebook/Instagram/Messenger, bare Android
  // WebViews, other known app browsers). Consumers use this to degrade
  // gracefully where those shells silently break downloads/printing.
  get isInAppBrowser() { return this.detect().isInAppBrowser; },
  // 'facebook' | 'instagram' | 'messenger' | 'android-webview' | 'other' | null
  get inAppBrowserKind() { return this.detect().inAppBrowserKind; },
  get isWeb() { return this.detect().isWeb; },
  get isIOS() { return this.detect().isIOS; },
  get isAndroid() { return this.detect().isAndroid; },
  get isHarmony() { return this.detect().isHarmony; },
  
  // Apply platform-specific CSS classes to document
  applyBodyClasses: function() {
    const p = this.detect();
    const body = document.body;
    if (!body) return;
    
    // Remove old classes
    body.classList.remove('platform-web', 'platform-ios', 'platform-android', 'platform-harmony', 'platform-capacitor', 'platform-inapp', 'is-touch', 'no-hover', 'is-mobile');

    // Add new classes
    if (p.isCapacitor) body.classList.add('platform-capacitor');
    body.classList.add(`platform-${p.platform}`);
    if (p.isTouch) body.classList.add('is-touch');
    if (!p.supportsHover) body.classList.add('no-hover');
    if (p.isMobile) body.classList.add('is-mobile');
    if (p.isInAppBrowser) body.classList.add('platform-inapp');
  }
};

// Apply platform classes immediately when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => Platform.applyBodyClasses());
} else {
  Platform.applyBodyClasses();
}

// ==========================================
// ROLE HELPERS
// ==========================================
// The server compares roles case-insensitively (server/main.py lowercases),
// but the client used to do exact-case checks like role === 'Admin'. A role
// stored as 'admin' would then pass ALL server permission checks while
// failing the client's UI checks — half-privileged, inconsistent behavior.
// These helpers make the client tolerant of case the same way the server is.
function isAdminRole(role) {
  return String(role || '').trim().toLowerCase() === 'admin';
}

function isDeliveryRole(role) {
  return String(role || '').trim().toLowerCase() === 'delivery';
}

// BATTERY SAVER: pause the infinite aurora background animations while the
// app/tab is hidden (style.css: body.app-hidden rules). Purely a GPU/battery
// win — the user never sees the page while it is hidden.
document.addEventListener('visibilitychange', () => {
  try {
    document.body.classList.toggle('app-hidden', document.visibilityState === 'hidden');
  } catch (_) {}
});

// ==========================================
// PERFORMANCE MODE (for weak/old devices)
// ==========================================
// The default look leans hard on the GPU: a viewport-sized aurora layer under
// filter:blur(110px) animating forever, a full-screen backdrop-blur overlay,
// and backdrop-filter blur(14px) on every glass panel. On an old laptop or a
// cheap phone that turns every scroll and repaint into a slideshow.
// body.perf-lite (style.css) keeps ALL features and the same layout but turns
// those decorations off. Preference is per-device (localStorage); lite is the
// DEFAULT — only an explicit 'full' choice in Settings enables the effects.

function isPerformanceModeOn() {
  let pref = null;
  try { pref = localStorage.getItem('albayan_perf_mode'); } catch (_) {}
  // Performance mode is the DEFAULT (user request): every device starts in
  // lite mode; only an explicit 'full' choice in Settings restores the heavy
  // glass/aurora effects. (Previously lite was only auto-enabled on weak
  // hardware via a deviceMemory/cores heuristic.)
  return pref !== 'full';
}

function applyPerformanceMode() {
  const lite = isPerformanceModeOn();
  try {
    if (document.body) document.body.classList.toggle('perf-lite', lite);
  } catch (_) {}
  return lite;
}

function togglePerformanceMode(on) {
  try { localStorage.setItem('albayan_perf_mode', on ? 'lite' : 'full'); } catch (_) {}
  applyPerformanceMode();
  if (typeof showNotification === 'function' && typeof state !== 'undefined') {
    const isAr = state.language === 'ar';
    showNotification(
      isAr ? 'وضع الأداء' : 'Performance Mode',
      on
        ? (isAr ? 'تم تفعيل وضع الأداء — التطبيق أخف وأسرع.' : 'Performance mode ON — lighter and faster.')
        : (isAr ? 'تم إيقاف وضع الأداء — عادت التأثيرات المرئية.' : 'Performance mode OFF — visual effects restored.'),
      'success'
    );
  }
}

// Apply immediately at load (script.js is at the end of <body>, so body
// exists) — before the first render, so there is no styled->lite flash.
applyPerformanceMode();

// ==========================================
// WORKSPACE EXPERIENCE
// ==========================================
// Albayan now has one consistent workspace: the complete Advanced view. Keep
// the compatibility helpers because older cached bundles and inline actions
// can still call them while a device updates, but never hide business tools.
const ALBAYAN_EXPERIENCE_MODE_KEY = 'albayan_experience_mode';

function getWorkspaceExperienceMode() {
  return 'advanced';
}

function isAdvancedWorkspaceMode() {
  return true;
}

function applyWorkspaceExperienceMode() {
  try {
    localStorage.removeItem(ALBAYAN_EXPERIENCE_MODE_KEY);
    if (document.body) {
      document.body.classList.add('workspace-advanced');
      document.body.classList.remove('workspace-simple');
    }
  } catch (_) {}
  return 'advanced';
}

function setWorkspaceExperienceMode(_mode, options = {}) {
  applyWorkspaceExperienceMode();

  // A full shell render refreshes the global header, navigation and every
  // progressive filter panel. Guard the calls because this module loads before
  // the renderer is declared in the generated bundle.
  if (options.render !== false) {
    if (typeof forceFullRender === 'function') forceFullRender();
    else if (typeof render === 'function') render();
  }

  return 'advanced';
}

function toggleWorkspaceExperienceMode() {
  return setWorkspaceExperienceMode('advanced');
}

// Apply before the first app render to avoid controls flashing open and then
// collapsing on startup.
applyWorkspaceExperienceMode();
// ==========================================
// CAPACITOR MOBILE RUNTIME
// ==========================================
// Native Android Back handling and a clear connectivity notice for the
// packaged app. The web app keeps normal browser history/online behaviour.

let _mobileRuntimeReady = false;
let _mobileLastBackAt = 0;
let _mobileServerReachable = true;
let _mobileColdStartBlocked = false;

function getCapacitorAppPlugin() {
  try {
    return window.Capacitor?.Plugins?.App || null;
  } catch (_) {
    return null;
  }
}

function isPackagedMobileApp() {
  return !!(typeof Platform !== 'undefined' && Platform.isCapacitor);
}

// Connectivity notices/gate apply to the packaged app AND phone browsers:
// a phone-browser user whose server is unreachable must see the retryable
// notice instead of a bare login screen (17-init.js calls this when defined).
function connectivityUiEnabled() {
  return isPackagedMobileApp() || (typeof Platform !== 'undefined' && Platform.isMobileBrowser === true);
}

function mobileRuntimeNeedsServer() {
  try {
    return typeof state === 'undefined' || String(state.serverModeOverride || 'auto') !== 'local';
  } catch (_) {
    return true;
  }
}

function mobileRuntimeIsArabic() {
  try { return typeof state !== 'undefined' && state.language === 'ar'; }
  catch (_) { return false; }
}

function removeMobileConnectivityNotice() {
  document.getElementById('mobile-connectivity-notice')?.remove();
}

function removeMobileConnectionGate() {
  document.getElementById('mobile-connection-gate')?.remove();
}

function renderMobileConnectionGate() {
  if (!connectivityUiEnabled() || !mobileRuntimeNeedsServer()) return;
  _mobileColdStartBlocked = true;
  removeMobileConnectivityNotice();
  const app = document.getElementById('app');
  if (!app) return;

  const isAr = mobileRuntimeIsArabic();
  const browserOffline = navigator.onLine === false;
  app.innerHTML = `
    <main id="mobile-connection-gate" class="min-h-screen flex items-center justify-center p-5" role="alert" aria-live="assertive">
      <section class="glass-panel w-full max-w-md rounded-3xl p-7 text-center">
        <div class="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300">
          <i data-lucide="wifi-off" class="h-8 w-8" aria-hidden="true"></i>
        </div>
        <h1 class="text-2xl font-extrabold text-slate-900 dark:text-white">
          ${browserOffline
            ? (isAr ? 'لا يوجد اتصال بالإنترنت' : 'No internet connection')
            : (isAr ? 'تعذّر الوصول إلى الخادم' : 'Server unavailable')}
        </h1>
        <p class="mt-3 text-sm leading-6 text-slate-600 dark:text-slate-300">
          ${isAr
            ? 'لم يتم تسجيل خروجك. يجب أن يتصل البيان بالخادم للتحقق من جلستك وتحميل بياناتك بأمان.'
            : 'You have not been signed out. Albayan must reach the server to verify your session and safely load your data.'}
        </p>
        <button type="button" onclick="retryMobileConnection()" class="mt-6 min-h-12 w-full rounded-xl bg-amber-600 px-5 py-3 font-extrabold text-white hover:bg-amber-700 disabled:cursor-wait disabled:opacity-60">
          ${isAr ? 'إعادة المحاولة' : 'Retry connection'}
        </button>
      </section>
    </main>`;
  try { if (typeof IconQueue !== 'undefined') IconQueue.schedule(app); } catch (_) {}
}

function setMobileColdStartBlocked(blocked) {
  _mobileColdStartBlocked = blocked === true;
  if (_mobileColdStartBlocked) renderMobileConnectionGate();
  else removeMobileConnectionGate();
}

function showMobileConnectivityNotice({ serverReachable = _mobileServerReachable } = {}) {
  if (!connectivityUiEnabled() || !mobileRuntimeNeedsServer()) {
    removeMobileConnectivityNotice();
    return;
  }

  _mobileServerReachable = serverReachable !== false;
  if (_mobileColdStartBlocked) {
    renderMobileConnectionGate();
    return;
  }
  const browserOffline = navigator.onLine === false;
  if (!browserOffline && _mobileServerReachable) {
    removeMobileConnectivityNotice();
    return;
  }

  const isAr = mobileRuntimeIsArabic();
  let notice = document.getElementById('mobile-connectivity-notice');
  if (!notice) {
    notice = document.createElement('section');
    notice.id = 'mobile-connectivity-notice';
    notice.setAttribute('role', 'status');
    notice.setAttribute('aria-live', 'polite');
    notice.className = 'fixed inset-x-3 z-[120] mx-auto max-w-xl rounded-2xl border border-amber-300 bg-amber-50 p-3 text-amber-950 shadow-2xl dark:border-amber-700 dark:bg-amber-950 dark:text-amber-100';
    notice.style.top = 'calc(var(--app-safe-top, 0px) + 0.75rem)';
    document.body.appendChild(notice);
  }

  const message = browserOffline
    ? (isAr ? 'لا يوجد اتصال بالإنترنت. ستبقى الشاشة الحالية ظاهرة، لكن الحفظ والمزامنة يحتاجان إلى الاتصال.' : 'No internet connection. Your current screen stays visible, but saving and syncing need a connection.')
    : (isAr ? 'تعذّر الوصول إلى خادم البيان. تحقق من الاتصال ثم أعد المحاولة.' : 'Albayan cannot reach the server. Check the connection and try again.');

  notice.innerHTML = `
    <div class="flex items-center gap-3">
      <i data-lucide="wifi-off" class="h-5 w-5 flex-none" aria-hidden="true"></i>
      <p class="min-w-0 flex-1 text-sm font-semibold">${message}</p>
      <button type="button" onclick="retryMobileConnection()" class="min-h-11 flex-none rounded-xl bg-amber-600 px-4 py-2 text-sm font-bold text-white hover:bg-amber-700 disabled:cursor-wait disabled:opacity-60">
        ${isAr ? 'إعادة المحاولة' : 'Retry'}
      </button>
    </div>`;
  try { if (typeof IconQueue !== 'undefined') IconQueue.schedule(notice); } catch (_) {}
}

async function retryMobileConnection() {
  if (!mobileRuntimeNeedsServer()) {
    removeMobileConnectivityNotice();
    return true;
  }
  const surface = document.getElementById('mobile-connection-gate') || document.getElementById('mobile-connectivity-notice');
  const button = surface?.querySelector('button');
  if (button) button.disabled = true;

  if (navigator.onLine === false) {
    if (_mobileColdStartBlocked) renderMobileConnectionGate();
    else showMobileConnectivityNotice({ serverReachable: false });
    return false;
  }

  let serverOk = false;
  try {
    serverOk = typeof apiHealthCheck === 'function' ? await apiHealthCheck() : true;
  } catch (_) {
    serverOk = false;
  }
  _mobileServerReachable = !!serverOk;

  if (!serverOk) {
    if (_mobileColdStartBlocked) renderMobileConnectionGate();
    else showMobileConnectivityNotice({ serverReachable: false });
    const retryButton = document.querySelector('#mobile-connection-gate button, #mobile-connectivity-notice button');
    if (retryButton) retryButton.disabled = false;
    return false;
  }

  removeMobileConnectivityNotice();
  removeMobileConnectionGate();
  if (typeof state !== 'undefined' && state.currentUser) {
    try {
      if (typeof serverLiveSyncOnce === 'function') await serverLiveSyncOnce();
    } catch (_) {
      showMobileConnectivityNotice({ serverReachable: false });
      return false;
    }
  } else {
    // A cold start while offline cannot restore the server session. Reload
    // only from the logged-out state so unsaved forms are never discarded.
    window.location.reload();
  }
  return true;
}

function updateMobileServerReachability(serverReachable) {
  _mobileServerReachable = serverReachable !== false;
  showMobileConnectivityNotice({ serverReachable: _mobileServerReachable });
}

function mobileSurfaceZIndex(element) {
  try {
    const computed = Number.parseInt(window.getComputedStyle(element).zIndex, 10);
    if (Number.isFinite(computed)) return computed;
  } catch (_) {}
  const classes = String(element?.className || '');
  const arbitrary = classes.match(/(?:^|\s)z-\[(\d+)\](?:\s|$)/);
  if (arbitrary) return Number(arbitrary[1]);
  const simple = classes.match(/(?:^|\s)z-(\d+)(?:\s|$)/);
  return simple ? Number(simple[1]) : 0;
}

function getTopMobileSurface() {
  const surfaces = Array.from(document.querySelectorAll(
    '.mobile-dialog-overlay, #receipt-photo-viewer, #command-palette-modal'
  )).filter(element => element && element.isConnected !== false);
  return surfaces
    .map((element, domOrder) => ({ element, domOrder, zIndex: mobileSurfaceZIndex(element) }))
    .sort((a, b) => (a.zIndex - b.zIndex) || (a.domOrder - b.domOrder))
    .pop()?.element || null;
}

function clearGenericMobileModalState(surface) {
  // A standalone overlay can still own ?modal=&id= (currently the receipt
  // collection dialog). Never clear an underlying tracked app-modal.
  const hasTrackedModalUnderneath = !!(typeof state !== 'undefined' && state.activeModal);
  if (!hasTrackedModalUnderneath) {
    try {
      const params = typeof getUrlParams === 'function' ? getUrlParams() : null;
      if (params?.modal && typeof clearUrlParams === 'function') clearUrlParams(['modal', 'id']);
    } catch (_) {}
    if (typeof state !== 'undefined') state.modalData = null;
  }
  if (surface?.id === 'collect-receipt-modal') {
    try { if (typeof _collectReceiptId !== 'undefined') _collectReceiptId = null; } catch (_) {}
    try { if (typeof _collectTargetLYD !== 'undefined') _collectTargetLYD = 0; } catch (_) {}
    try { if (typeof _tempCollectPayments !== 'undefined') _tempCollectPayments = []; } catch (_) {}
  }
}

function closeTopMobileSurface() {
  const topSurface = getTopMobileSurface();
  if (!topSurface) {
    if (typeof state !== 'undefined' && state.isMobileMenuOpen) {
      state.isMobileMenuOpen = false;
      if (typeof forceFullRender === 'function') forceFullRender();
      else if (typeof render === 'function') render();
      return true;
    }
    return false;
  }

  if (topSurface.id === 'command-palette-modal') {
    if (typeof state !== 'undefined') state.commandPaletteOpen = false;
    topSurface.remove();
    return true;
  }

  if (topSurface.id === 'receipt-photo-viewer') {
    if (typeof closeReceiptPhotoViewer === 'function') closeReceiptPhotoViewer();
    else topSurface.remove();
    return true;
  }

  if (topSurface.id === 'customer-pages-dialog') {
    if (typeof closeCustomerPagesDialog === 'function') closeCustomerPagesDialog();
    else topSurface.remove();
    return true;
  }

  // This alert requires an explicit decision. Android Back follows the safe
  // "choose another customer" path instead of merely deleting the overlay and
  // leaving an unacknowledged customer selected underneath it.
  if (topSurface.id === 'receipt-customer-risk-warning') {
    if (typeof cancelReceiptCustomerRiskWarning === 'function') cancelReceiptCustomerRiskWarning();
    else topSurface.remove();
    return true;
  }

  if (topSurface.id === 'app-modal') {
    if (typeof closeModal === 'function') closeModal();
    else {
      topSurface.remove();
      clearGenericMobileModalState(topSurface);
    }
    return true;
  }

  // Delivery, collect, history and chooser dialogs are standalone overlays
  // without activeModal state. Clean their URL/working state as well as DOM.
  // The driver completion form keeps a crash-recovery draft; write the
  // pending debounced keystrokes before Back destroys the DOM the draft
  // writer reads from (the timer would no-op after removal).
  if (topSurface.id === 'delivery-complete-modal' && typeof _flushDeliveryCompletionDraftNow === 'function') {
    try { _flushDeliveryCompletionDraftNow(); } catch (_) {}
  }
  topSurface.remove();
  clearGenericMobileModalState(topSurface);
  return true;
}

function getMobileLandingView() {
  if (typeof state === 'undefined' || !state.currentUser) return '';
  if (typeof isAdminRole === 'function' && isAdminRole(state.currentUser.role)) return 'services-hub';
  if (typeof getPostLoginLandingViewForUser === 'function') {
    return getPostLoginLandingViewForUser(state.currentUser);
  }
  return state.currentView || '';
}

async function handleAndroidBackButton(event = {}) {
  if (closeTopMobileSurface()) {
    _mobileLastBackAt = 0;
    return;
  }

  const landingView = getMobileLandingView();
  const currentView = typeof state !== 'undefined' ? String(state.currentView || '') : '';
  if (landingView && currentView && currentView !== landingView) {
    _mobileLastBackAt = 0;
    if (event.canGoBack) window.history.back();
    else if (typeof navigateToInternal === 'function') navigateToInternal(landingView, true);
    return;
  }

  const now = Date.now();
  if (now - _mobileLastBackAt <= 2000) {
    const App = getCapacitorAppPlugin();
    if (App?.exitApp) await App.exitApp();
    return;
  }

  _mobileLastBackAt = now;
  const isAr = mobileRuntimeIsArabic();
  if (typeof showNotification === 'function') {
    showNotification(
      isAr ? 'الخروج من البيان' : 'Exit Albayan',
      isAr ? 'اضغط رجوع مرة أخرى للخروج.' : 'Press Back again to exit.',
      'info'
    );
  }
}

async function setupMobileRuntime() {
  // Phone browsers get the connectivity notice/gate too; the Android
  // backButton listener below stays Capacitor-only (plugin guards).
  if (_mobileRuntimeReady || !connectivityUiEnabled()) return;
  _mobileRuntimeReady = true;

  // Install viewport/keyboard handling for phone browsers and the secure
  // native bridges for packaged iOS/Android before registering deep links.
  if (typeof setupNativeServices === 'function') {
    await setupNativeServices();
  }

  window.addEventListener('offline', () => showMobileConnectivityNotice({ serverReachable: false }));
  window.addEventListener('online', () => {
    // Browser connectivity returned; verify Albayan itself before hiding the
    // warning. This also restores a cold-start session when appropriate.
    retryMobileConnection().catch(() => showMobileConnectivityNotice({ serverReachable: false }));
  });
  showMobileConnectivityNotice({ serverReachable: navigator.onLine !== false });

  if (typeof Platform !== 'undefined' && Platform.isAndroid) {
    const App = getCapacitorAppPlugin();
    if (App?.addListener) {
      try {
        await App.addListener('backButton', handleAndroidBackButton);
      } catch (error) {
        console.warn('[MobileRuntime] Android Back listener unavailable:', error?.message || error);
      }
    }
  }

  // SYSTEM-BROWSER APP LOGIN (Phase 2): listen for the albayan://auth deep
  // link that brings a finished browser sign-in back into the packaged app
  // (Capacitor-only; the function guards itself).
  if (typeof setupAppLoginDeepLinks === 'function') {
    setupAppLoginDeepLinks().catch((error) => {
      console.warn('[MobileRuntime] App-login deep links unavailable:', error?.message || error);
    });
  }
}

// ==========================================
// PHONE BROWSER BACK + OVERLAY HISTORY MODEL
// ==========================================
// DESIGN:
// 1) Tracked #app-modal dialogs push a ?modal=&id= entry on open
//    (updateUrlParams stamps it { albayanModal: true }); every OTHER
//    standalone surface (photo viewer, confirm dialogs, command palette) gets
//    one same-URL sentinel entry ({ overlaySentinel: true }) pushed centrally
//    by the <body> observer below, so the ~19 creation sites need no edits.
//    The nav drawer pushes its own sentinel in toggleMobileMenu because it
//    renders inside #app where the body observer cannot see it.
// 2) Hardware/gesture Back pops that entry; the popstate handler
//    (setupUrlRouting, 11-routing-cloud.js) closes the top surface via
//    closeTopMobileSurface() and stops — the view underneath never navigates
//    and unsaved form state (temp photos, top-ups…) survives.
// 3) Closing with X/Cancel/backdrop instead consumes the entry via
//    history.back() (closeModal, toggleMobileMenu, the observer), and that
//    popstate is flagged as bookkeeping so the router never re-renders or
//    scroll-resets the unchanged view.
// 4) A navigation that starts while a sentinel is on top REPLACES it
//    (navigateToInternal), keeping Back balanced after drawer/palette navs.
// 5) Capacitor keeps its native backButton path (isPackagedMobileApp() gates
//    the sentinel/popstate logic off); desktop keeps today's behaviour — no
//    sentinels, but closeModal still consumes its own ?modal entries.

let _overlaySentinelDepth = 0;          // sentinels pushed and not yet consumed this session
let _albayanLastModalUrlPushAt = 0;     // set by updateUrlParams({ modal… }) — see 11-routing-cloud.js
let _lastOverlayPopCloseAt = 0;         // a Back press just closed a surface (entry already popped)
let _suppressOverlayPopstateUntil = 0;  // our own balancing history.back() is in flight
let _closingSurfaceFromPopstate = false;

function isPhoneBrowserHistoryManaged() {
  return !isPackagedMobileApp() && typeof Platform !== 'undefined' && !!Platform.isMobile;
}

function pushMobileOverlayHistoryEntry() {
  if (!isPhoneBrowserHistoryManaged()) return;
  try {
    // Same-URL entry: Back pops it and the popstate handler turns the pop
    // into "close the top overlay". albayanModal is explicitly cleared so
    // closeModal() never mistakes a sentinel for a tracked-modal entry;
    // underAlbayanModal remembers that the dialog's own ?modal entry sits
    // directly beneath this sentinel (overlay opened late over a tracked
    // modal — e.g. the duplicate-serial warning), so closeModal() can
    // consume BOTH entries when it tears the whole stack down at once.
    window.history.pushState(
      Object.assign({}, window.history.state || {}, {
        overlaySentinel: true,
        albayanModal: false,
        underAlbayanModal: !!(window.history.state && window.history.state.albayanModal)
      }),
      '', window.location.href
    );
    _overlaySentinelDepth++;
  } catch (_) {}
}

function consumeOverlayHistoryEntry() {
  // Pop the entry that open pushed. The popstate this triggers is pure
  // bookkeeping (the surface is already closed), so flag it for the router.
  _suppressOverlayPopstateUntil = Date.now() + 800;
  try {
    window.history.back();
    return true;
  } catch (_) {
    _suppressOverlayPopstateUntil = 0;
    return false;
  }
}

function _overlayHistoryConsumePending() {
  return Date.now() < _suppressOverlayPopstateUntil;
}

function shouldSuppressOverlayPopstate() {
  const suppress = _overlayHistoryConsumePending();
  _suppressOverlayPopstateUntil = 0; // one-shot: never swallow a real Back
  return suppress;
}

function markOverlayPopClose(closed) {
  if (closed) {
    _lastOverlayPopCloseAt = Date.now();
    // The popped entry was the surface's sentinel/?modal entry. Depth may
    // under-count after a tracked-modal pop; under-counting only ever makes
    // the observer SKIP an auto-consume (the old status quo), never over-pop.
    if (_overlaySentinelDepth > 0) _overlaySentinelDepth--;
  }
  return !!closed;
}

// ==========================================
// CENTRAL OVERLAY OBSERVER (history + iOS body scroll lock)
// ==========================================
// Every standalone surface is appended directly to <body> (verified across
// src/), so one childList observer is the single hook for all creation
// sites: it pushes/consumes the sentinel entries above and toggles a body
// scroll lock while any dialog is open. The lock matters on iOS < 16, where
// overscroll-behavior (style.css) is unsupported: drags inside a dialog
// scrolled the page underneath, and at scrollTop 0 triggered pull-to-refresh
// — reloading the SPA and discarding half-filled forms. The existing CSS
// stays as the iOS 16+/Android fast path.

let _overlayObservedCount = 0;
let _scrollLockActive = false;
let _scrollLockY = 0;

function _overlaySurfaceCount() {
  return document.querySelectorAll(
    '.mobile-dialog-overlay, #receipt-photo-viewer, #command-palette-modal'
  ).length;
}

function _lockBodyScrollForOverlay() {
  if (_scrollLockActive) return;
  // Same media condition as the .mobile-dialog-overlay scroll rules in
  // style.css — phones and short landscape windows; desktop stays untouched.
  try {
    if (!window.matchMedia('(max-width: 900px), (max-height: 500px)').matches) return;
  } catch (_) { return; }
  _scrollLockY = window.scrollY || window.pageYOffset || 0;
  const bodyStyle = document.body.style;
  bodyStyle.position = 'fixed';
  bodyStyle.top = (-_scrollLockY) + 'px';
  bodyStyle.left = '0';
  bodyStyle.right = '0';
  bodyStyle.width = '100%';
  _scrollLockActive = true;
}

function _unlockBodyScrollForOverlay() {
  if (!_scrollLockActive) return;
  _scrollLockActive = false;
  const bodyStyle = document.body.style;
  bodyStyle.position = '';
  bodyStyle.top = '';
  bodyStyle.left = '';
  bodyStyle.right = '';
  bodyStyle.width = '';
  const y = _scrollLockY;
  window.scrollTo(0, y);
  // closeModal triggers render(), whose own scroll save/restore may read
  // scrollY as 0 while the body was still position:fixed — restore again
  // after that render had its chance to run.
  requestAnimationFrame(() => window.scrollTo(0, y));
}

function _handleOverlayDomChange() {
  const count = _overlaySurfaceCount();
  const previous = _overlayObservedCount;
  if (count === previous) return;
  _overlayObservedCount = count;

  if (count > previous) {
    // Surface(s) opened. If the opener itself just pushed a ?modal history
    // entry (all tracked #app-modal openers and the collect-receipt dialog
    // do, via updateUrlParams), Back already has an entry to consume — a
    // sentinel too would cost the user an extra Back press. One sentinel per
    // transition: batch-opens of several untracked surfaces in one task are
    // not a real flow.
    if (Date.now() - _albayanLastModalUrlPushAt > 400) {
      pushMobileOverlayHistoryEntry();
    }
  } else {
    // Surface(s) closed by their own X/Cancel/backdrop handler. A Back-press
    // close is excluded via _lastOverlayPopCloseAt (entry already popped),
    // and an in-flight closeModal consume via _overlayHistoryConsumePending.
    const backJustClosedIt = Date.now() - _lastOverlayPopCloseAt <= 300;
    const entryState = window.history.state;
    if (isPhoneBrowserHistoryManaged() && !backJustClosedIt && !_overlayHistoryConsumePending()) {
      if (entryState && entryState.overlaySentinel && _overlaySentinelDepth > 0) {
        _overlaySentinelDepth--;
        consumeOverlayHistoryEntry();
      } else if (entryState && entryState.albayanModal && count === 0
                 && (typeof state === 'undefined' || !state.activeModal)) {
        // Untracked ?modal surface (collect-receipt) closed by its inline
        // backdrop/X remove(): its own pushed entry is on top — consume it.
        consumeOverlayHistoryEntry();
      }
    }
  }

  if (count > 0 && previous === 0) _lockBodyScrollForOverlay();
  else if (count === 0 && previous > 0) _unlockBodyScrollForOverlay();
}

let _overlayObserverInstalled = false;
function setupOverlaySurfaceObserver() {
  if (_overlayObserverInstalled) return;
  if (typeof MutationObserver === 'undefined' || !document.body) return;
  _overlayObserverInstalled = true;
  try {
    const observer = new MutationObserver(_handleOverlayDomChange);
    // childList only: all overlay surfaces are direct <body> children.
    observer.observe(document.body, { childList: true });
    _overlayObservedCount = _overlaySurfaceCount();
  } catch (_) {
    _overlayObserverInstalled = false;
  }
}
// script.js executes at the end of <body>, so document.body exists here.
setupOverlaySurfaceObserver();
// ==========================================
// NATIVE DEVICE SERVICES
// ==========================================
// This module is the single bridge between Albayan's shared web code and the
// iOS/Android shell. Every feature has a browser fallback, so the website and
// PWA remain fully usable without Capacitor plugins.

const NATIVE_SECURE_PREFIX = 'albayan_secure_v1_';
const NATIVE_PHOTO_PENDING_KEY = 'albayan_native_photo_pending';
const NATIVE_APP_LOCK_AFTER_MS = 30 * 1000;
const NATIVE_REMINDER_LIMIT = 50;

let _nativeServicesPromise = null;
let _nativeViewportFrame = 0;
let _nativeBackgroundedAt = 0;
let _nativeUnlockBusy = false;
let _nativeReminderTimer = null;
let _nativePrefs = {
  ready: false,
  biometricEnabled: false,
  remindersEnabled: false,
  biometricInfo: null
};

function getCapacitorPlugin(name) {
  if (!isPackagedMobileApp()) return null;
  try { return window.Capacitor?.Plugins?.[name] || null; }
  catch (_) { return null; }
}

function nativeFeatureAvailable(name, method = '') {
  const plugin = getCapacitorPlugin(name);
  return !!(plugin && (!method || typeof plugin[method] === 'function'));
}

async function _addNativeListener(plugin, eventName, handler) {
  if (!plugin?.addListener) return null;
  try {
    return await plugin.addListener(eventName, handler);
  } catch (error) {
    if (ALBAYAN_DEBUG_MODE) console.warn(`[NativeServices] ${eventName} listener unavailable:`, error?.message || error);
    return null;
  }
}

// Raw bridge calls are intentional here. The app is vanilla JS (not bundled
// ESM), while the plugin's JavaScript wrapper normally performs these same
// calls. ThisDeviceOnly prevents secrets migrating to a different iPhone.
async function nativeSecureGet(key) {
  const plugin = getCapacitorPlugin('SecureStorage');
  if (!plugin?.internalGetItem) return null;
  try {
    const result = await plugin.internalGetItem({
      prefixedKey: NATIVE_SECURE_PREFIX + String(key || ''),
      sync: false
    });
    if (result?.data == null || result.data === '') return null;
    return JSON.parse(result.data);
  } catch (error) {
    if (ALBAYAN_DEBUG_MODE) console.warn('[NativeSecure] Read failed:', error?.message || error);
    return null;
  }
}

async function nativeSecureSet(key, value) {
  const plugin = getCapacitorPlugin('SecureStorage');
  if (!plugin?.internalSetItem) return false;
  try {
    await plugin.internalSetItem({
      prefixedKey: NATIVE_SECURE_PREFIX + String(key || ''),
      data: JSON.stringify(value),
      sync: false,
      access: 1 // KeychainAccess.whenUnlockedThisDeviceOnly; ignored on Android.
    });
    return true;
  } catch (error) {
    console.warn('[NativeSecure] Write failed:', error?.message || error);
    return false;
  }
}

async function nativeSecureRemove(key) {
  const plugin = getCapacitorPlugin('SecureStorage');
  if (!plugin?.internalRemoveItem) return false;
  try {
    await plugin.internalRemoveItem({
      prefixedKey: NATIVE_SECURE_PREFIX + String(key || ''),
      sync: false
    });
    return true;
  } catch (_) {
    return false;
  }
}

async function openNativeBrowser(url) {
  const safeUrl = String(url || '');
  if (!/^https:\/\//i.test(safeUrl)) return false;
  const browser = getCapacitorPlugin('Browser');
  if (browser?.open) {
    try {
      await browser.open({
        url: safeUrl,
        toolbarColor: '#0f4cdb',
        presentationStyle: 'fullscreen'
      });
      return true;
    } catch (error) {
      console.warn('[NativeBrowser] Open failed:', error?.message || error);
    }
  }
  try { return !!window.open(safeUrl, '_blank', 'noopener,noreferrer'); }
  catch (_) { return false; }
}

async function closeNativeBrowser() {
  const browser = getCapacitorPlugin('Browser');
  if (!browser?.close) return;
  try { await browser.close(); } catch (_) {}
}

async function nativeHaptic(kind = 'light') {
  const haptics = getCapacitorPlugin('Haptics');
  if (!haptics) return false;
  try {
    if (kind === 'success' && haptics.notification) {
      await haptics.notification({ type: 'SUCCESS' });
    } else if (kind === 'warning' && haptics.notification) {
      await haptics.notification({ type: 'WARNING' });
    } else if (haptics.impact) {
      await haptics.impact({ style: kind === 'medium' ? 'MEDIUM' : 'LIGHT' });
    }
    return true;
  } catch (_) { return false; }
}

async function nativeWriteClipboardText(value) {
  const clipboard = getCapacitorPlugin('Clipboard');
  if (!clipboard?.write) return false;
  try {
    await clipboard.write({ string: String(value ?? '') });
    await nativeHaptic('light');
    return true;
  } catch (_) { return false; }
}

function _nativeDataUrlToFile(dataUrl, fallbackName = 'photo') {
  const match = String(dataUrl || '').match(/^data:(image\/(?:png|jpe?g|gif|webp));base64,([a-z0-9+/=]+)$/i);
  if (!match) return null;
  try {
    const binary = atob(match[2]);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const extension = /png/i.test(match[1]) ? 'png' : /webp/i.test(match[1]) ? 'webp' : /gif/i.test(match[1]) ? 'gif' : 'jpg';
    const blob = new Blob([bytes], { type: match[1] });
    return typeof File === 'function'
      ? new File([blob], `${fallbackName}.${extension}`, { type: match[1], lastModified: Date.now() })
      : blob;
  } catch (_) { return null; }
}

async function readNativeClipboardImage() {
  const clipboard = getCapacitorPlugin('Clipboard');
  if (!clipboard?.read) return null;
  try {
    const result = await clipboard.read();
    if (!String(result?.type || '').toLowerCase().startsWith('image/')) return null;
    return _nativeDataUrlToFile(result.value, 'clipboard-photo');
  } catch (_) { return null; }
}

async function readNativeClipboardText() {
  const clipboard = getCapacitorPlugin('Clipboard');
  if (!clipboard?.read) return '';
  try {
    const result = await clipboard.read();
    if (String(result?.type || '').toLowerCase().startsWith('image/')) return '';
    return String(result?.value || '');
  } catch (_) { return ''; }
}

async function nativeShareContent({ title = 'Albayan', text = '', url = '' } = {}) {
  const share = getCapacitorPlugin('Share');
  if (share?.share) {
    try {
      await share.share({
        title: String(title || 'Albayan').slice(0, 120),
        text: String(text || '').slice(0, 8000),
        ...(url ? { url: String(url) } : {}),
        dialogTitle: String(title || 'Albayan').slice(0, 120)
      });
      await nativeHaptic('success');
      return true;
    } catch (error) {
      // Closing the native share sheet is a normal cancellation, not an error.
      if (!/cancel/i.test(String(error?.message || error))) console.warn('[NativeShare] Failed:', error?.message || error);
      return false;
    }
  }
  if (navigator?.share) {
    try {
      await navigator.share({ title, text, ...(url ? { url } : {}) });
      return true;
    } catch (_) { return false; }
  }
  return false;
}

function _nativePhotoFallbackInput(target) {
  const zone = document.querySelector(`[data-photo-paste-target="${String(target || '')}"]`);
  return zone?.querySelector('input[type="file"]') || null;
}

async function _nativeCameraResultToFile(result) {
  const source = String(result?.webPath || result?.path || '').trim();
  if (!source) return null;
  try {
    const response = await fetch(source);
    const blob = await response.blob();
    const type = blob.type || `image/${String(result?.format || 'jpeg').replace('jpg', 'jpeg')}`;
    return typeof File === 'function'
      ? new File([blob], `albayan-camera-${Date.now()}.${/png/i.test(type) ? 'png' : 'jpg'}`, { type, lastModified: Date.now() })
      : blob;
  } catch (error) {
    console.warn('[NativeCamera] Could not read photo:', error?.message || error);
    return null;
  }
}

async function _deliverNativeCameraResult(result, target, context, attempts = 0) {
  const resolvedTarget = String(target || '');
  if (context != null && typeof capturePhotoPasteContext === 'function' && attempts === 0 && context !== capturePhotoPasteContext(resolvedTarget)) return false;
  if (typeof _photoPasteTargetIsAvailable === 'function' && !_photoPasteTargetIsAvailable(resolvedTarget)) {
    if (attempts < 40) {
      setTimeout(() => _deliverNativeCameraResult(result, resolvedTarget, null, attempts + 1), 250);
      return true;
    }
    showNotification(
      state.language === 'ar' ? 'افتح النموذج مرة أخرى' : 'Open the form again',
      state.language === 'ar' ? 'عاد التطبيق من الكاميرا، لكن نموذج الصورة لم يعد مفتوحاً.' : 'Albayan returned from the camera, but the photo form is no longer open.',
      'warning'
    );
    return false;
  }
  const file = await _nativeCameraResultToFile(result);
  if (!file) return false;
  const routed = typeof _routePastedPhotoFiles === 'function' && _routePastedPhotoFiles(resolvedTarget, [file]);
  if (routed) {
    try { localStorage.removeItem(NATIVE_PHOTO_PENDING_KEY); } catch (_) {}
    await nativeHaptic('success');
  }
  return !!routed;
}

async function takeNativePhoto(requestedTarget = '') {
  const target = typeof resolvePhotoPasteTarget === 'function'
    ? resolvePhotoPasteTarget(document.activeElement, requestedTarget)
    : String(requestedTarget || '');
  if (!target) return false;
  const camera = getCapacitorPlugin('Camera');
  if (!camera?.getPhoto) {
    const input = _nativePhotoFallbackInput(target);
    input?.click?.();
    return !!input;
  }
  if (target === 'delivery' && typeof _flushDeliveryCompletionDraftNow === 'function') {
    _flushDeliveryCompletionDraftNow();
  }
  const context = typeof capturePhotoPasteContext === 'function' ? capturePhotoPasteContext(target) : null;
  try {
    localStorage.setItem(NATIVE_PHOTO_PENDING_KEY, JSON.stringify({ target, createdAt: Date.now() }));
  } catch (_) {}
  try {
    const result = await camera.getPhoto({
      quality: 88,
      width: 1600,
      height: 1600,
      allowEditing: false,
      resultType: 'uri',
      source: 'CAMERA',
      direction: 'REAR',
      saveToGallery: false,
      correctOrientation: true,
      presentationStyle: 'fullscreen'
    });
    return await _deliverNativeCameraResult(result, target, context);
  } catch (error) {
    if (!/cancel/i.test(String(error?.message || error))) {
      showNotification(
        state.language === 'ar' ? 'تعذّر فتح الكاميرا' : 'Camera unavailable',
        state.language === 'ar' ? 'تحقق من إذن الكاميرا ثم حاول مرة أخرى.' : 'Check the camera permission and try again.',
        'error'
      );
    }
    return false;
  }
}

function _updateVisualViewportVariables() {
  _nativeViewportFrame = 0;
  const viewport = window.visualViewport;
  const height = Math.max(1, Math.round(viewport?.height || window.innerHeight || 1));
  const width = Math.max(1, Math.round(viewport?.width || window.innerWidth || 1));
  const top = Math.max(0, Math.round(viewport?.offsetTop || 0));
  document.documentElement.style.setProperty('--app-visual-height', `${height}px`);
  document.documentElement.style.setProperty('--app-visual-width', `${width}px`);
  document.documentElement.style.setProperty('--app-visual-offset-top', `${top}px`);
  const keyboardLikelyOpen = height < Math.max(360, (window.innerHeight || height) * 0.72);
  document.body.classList.toggle('keyboard-open', keyboardLikelyOpen || document.body.classList.contains('native-keyboard-open'));
}

function queueVisualViewportUpdate() {
  if (_nativeViewportFrame) return;
  _nativeViewportFrame = requestAnimationFrame(_updateVisualViewportVariables);
}

function setupAdaptiveViewport() {
  queueVisualViewportUpdate();
  window.addEventListener('resize', queueVisualViewportUpdate, { passive: true });
  window.addEventListener('orientationchange', queueVisualViewportUpdate, { passive: true });
  window.visualViewport?.addEventListener('resize', queueVisualViewportUpdate, { passive: true });
  window.visualViewport?.addEventListener('scroll', queueVisualViewportUpdate, { passive: true });
}

function _setNativeKeyboardOpen(open, keyboardHeight = 0) {
  document.body.classList.toggle('native-keyboard-open', open === true);
  document.body.classList.toggle('keyboard-open', open === true);
  document.documentElement.style.setProperty('--app-keyboard-height', `${Math.max(0, Number(keyboardHeight) || 0)}px`);
  queueVisualViewportUpdate();
}

async function getNativeBiometricInfo(refresh = false) {
  if (_nativePrefs.biometricInfo && !refresh) return _nativePrefs.biometricInfo;
  const biometric = getCapacitorPlugin('BiometricAuthNative');
  if (!biometric?.checkBiometry) return null;
  try {
    _nativePrefs.biometricInfo = await biometric.checkBiometry();
    return _nativePrefs.biometricInfo;
  } catch (_) { return null; }
}

async function authenticateNativeDevice(reason = '') {
  const biometric = getCapacitorPlugin('BiometricAuthNative');
  if (!biometric?.internalAuthenticate) return false;
  const info = await getNativeBiometricInfo(true);
  if (!info?.isAvailable && !info?.deviceIsSecure) return false;
  try {
    await biometric.internalAuthenticate({
      reason: reason || (state.language === 'ar' ? 'افتح تطبيق البيان' : 'Unlock Albayan'),
      cancelTitle: state.language === 'ar' ? 'إلغاء' : 'Cancel',
      allowDeviceCredential: true,
      iosFallbackTitle: state.language === 'ar' ? 'استخدم رمز الجهاز' : 'Use device passcode',
      androidTitle: state.language === 'ar' ? 'افتح البيان' : 'Unlock Albayan',
      androidSubtitle: state.language === 'ar' ? 'استخدم البصمة أو رمز الجهاز' : 'Use biometrics or your device credential',
      androidConfirmationRequired: false,
      androidBiometryStrength: 0
    });
    return true;
  } catch (error) {
    if (!/cancel|systemCancel|appCancel/i.test(String(error?.code || error?.message || error))) {
      console.warn('[NativeSecurity] Authentication failed:', error?.code || error?.message || error);
    }
    return false;
  }
}

function renderNativeAppLock() {
  if (!isPackagedMobileApp() || !_nativePrefs.biometricEnabled || !state?.currentUser) return;
  let lock = document.getElementById('native-app-lock');
  if (!lock) {
    lock = document.createElement('section');
    lock.id = 'native-app-lock';
    lock.className = 'native-app-lock';
    lock.setAttribute('role', 'dialog');
    lock.setAttribute('aria-modal', 'true');
    document.body.appendChild(lock);
  }
  const isAr = state.language === 'ar';
  lock.setAttribute('dir', isAr ? 'rtl' : 'ltr');
  lock.innerHTML = `
    <div class="native-app-lock-card">
      <div class="native-app-lock-icon"><i data-lucide="scan-face" class="h-9 w-9"></i></div>
      <h1>${isAr ? 'البيان مقفل' : 'Albayan is locked'}</h1>
      <p>${isAr ? 'استخدم البصمة أو Face ID أو رمز قفل الهاتف لحماية بيانات العمل.' : 'Use biometrics or your phone passcode to protect business data.'}</p>
      <button type="button" onclick="unlockNativeApp()" class="native-app-lock-button" ${_nativeUnlockBusy ? 'disabled' : ''}>
        ${_nativeUnlockBusy ? (isAr ? 'جارٍ التحقق...' : 'Checking...') : (isAr ? 'فتح التطبيق' : 'Unlock app')}
      </button>
    </div>`;
  try { IconQueue.schedule(lock); } catch (_) {}
  document.body.classList.add('native-app-locked');
}

function removeNativeAppLock() {
  document.getElementById('native-app-lock')?.remove();
  document.body.classList.remove('native-app-locked');
}

async function unlockNativeApp() {
  if (_nativeUnlockBusy) return false;
  _nativeUnlockBusy = true;
  renderNativeAppLock();
  const ok = await authenticateNativeDevice();
  _nativeUnlockBusy = false;
  if (ok) {
    removeNativeAppLock();
    await nativeHaptic('success');
  } else {
    renderNativeAppLock();
  }
  return ok;
}

async function setNativeBiometricLockEnabled(enabled) {
  if (!isPackagedMobileApp()) return false;
  const next = enabled === true;
  if (next) {
    const info = await getNativeBiometricInfo(true);
    if (!info?.isAvailable && !info?.deviceIsSecure) {
      showNotification(
        state.language === 'ar' ? 'حماية الهاتف غير جاهزة' : 'Device protection unavailable',
        state.language === 'ar' ? 'فعّل بصمة أو Face ID أو رمز قفل للهاتف أولاً.' : 'Set up biometrics or a phone passcode first.',
        'warning'
      );
      return false;
    }
    if (!(await authenticateNativeDevice(state.language === 'ar' ? 'فعّل حماية البيان' : 'Enable Albayan protection'))) return false;
  } else if (_nativePrefs.biometricEnabled) {
    if (!(await authenticateNativeDevice(state.language === 'ar' ? 'أوقف حماية البيان' : 'Disable Albayan protection'))) return false;
  }
  const saved = await nativeSecureSet('biometric_lock_enabled', next);
  if (!saved) return false;
  _nativePrefs.biometricEnabled = next;
  if (!next) removeNativeAppLock();
  if (state.currentView === 'settings') render();
  showNotification(
    state.language === 'ar' ? 'تم تحديث حماية الجهاز' : 'Device protection updated',
    next
      ? (state.language === 'ar' ? 'سيُقفل البيان عند مغادرة التطبيق.' : 'Albayan will lock after you leave the app.')
      : (state.language === 'ar' ? 'تم إيقاف قفل التطبيق على هذا الجهاز.' : 'App lock is off on this device.'),
    'success'
  );
  return true;
}

function nativeSecuritySettingsStatus() {
  return {
    isNative: isPackagedMobileApp(),
    ready: _nativePrefs.ready,
    biometricEnabled: _nativePrefs.biometricEnabled,
    remindersEnabled: _nativePrefs.remindersEnabled,
    biometricAvailable: !!(_nativePrefs.biometricInfo?.isAvailable || _nativePrefs.biometricInfo?.deviceIsSecure)
  };
}

function _nativeReminderId(adId) {
  const value = String(adId || '');
  let hash = 2166136261;
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return 100000 + (Math.abs(hash >>> 0) % 1900000000);
}

async function syncNativeReconciliationReminders() {
  if (!isPackagedMobileApp() || !_nativePrefs.remindersEnabled || !state?.currentUser) return false;
  const notifications = getCapacitorPlugin('LocalNotifications');
  if (!notifications?.schedule || !notifications?.getPending) return false;
  const now = new Date();
  const candidates = (Array.isArray(state.ads) ? state.ads : [])
    .filter(ad => ad && !ad._deleted && typeof getAdReconciliationAvailableDay === 'function')
    .map(ad => ({ ad, at: getAdReconciliationAvailableDay(ad) }))
    .filter(item => item.at instanceof Date && Number.isFinite(item.at.getTime()) && item.at.getTime() > now.getTime())
    .sort((a, b) => a.at - b.at)
    .slice(0, NATIVE_REMINDER_LIMIT);
  const desired = new Map();
  for (const item of candidates) {
    const at = new Date(item.at);
    at.setHours(9, 0, 0, 0);
    if (at.getTime() <= now.getTime()) at.setTime(now.getTime() + 60 * 1000);
    const id = _nativeReminderId(item.ad.id);
    desired.set(id, {
      id,
      title: state.language === 'ar' ? 'إعلان يحتاج تسوية' : 'Ad ready for reconciliation',
      body: state.language === 'ar' ? 'أدخل المصروف الفعلي وأرجع المتبقي للعميل.' : 'Enter the actual spend and return any remainder to the customer.',
      schedule: { at, allowWhileIdle: true },
      extra: { albayanType: 'reconciliation', adId: String(item.ad.id) }
    });
  }
  try {
    const pending = await notifications.getPending();
    const old = (pending?.notifications || []).filter(note => note?.extra?.albayanType === 'reconciliation');
    if (old.length && notifications.cancel) await notifications.cancel({ notifications: old.map(note => ({ id: note.id })) });
    if (desired.size) await notifications.schedule({ notifications: Array.from(desired.values()) });
    return true;
  } catch (error) {
    console.warn('[NativeNotifications] Sync failed:', error?.message || error);
    return false;
  }
}

function queueNativeReminderSync() {
  if (!isPackagedMobileApp() || !_nativePrefs.remindersEnabled) return;
  clearTimeout(_nativeReminderTimer);
  _nativeReminderTimer = setTimeout(() => syncNativeReconciliationReminders(), 900);
}

async function setNativeRemindersEnabled(enabled) {
  if (!isPackagedMobileApp()) return false;
  const notifications = getCapacitorPlugin('LocalNotifications');
  if (!notifications) return false;
  const next = enabled === true;
  if (next) {
    try {
      let permission = await notifications.checkPermissions();
      if (permission?.display !== 'granted') permission = await notifications.requestPermissions();
      if (permission?.display !== 'granted') {
        showNotification(
          state.language === 'ar' ? 'الإشعارات غير مسموحة' : 'Notifications not allowed',
          state.language === 'ar' ? 'اسمح بالإشعارات من إعدادات الهاتف ثم حاول مرة أخرى.' : 'Allow notifications in your phone settings, then try again.',
          'warning'
        );
        return false;
      }
    } catch (_) { return false; }
  }
  if (!(await nativeSecureSet('reconciliation_reminders_enabled', next))) return false;
  _nativePrefs.remindersEnabled = next;
  if (next) queueNativeReminderSync();
  else {
    try {
      const pending = await notifications.getPending();
      const old = (pending?.notifications || []).filter(note => note?.extra?.albayanType === 'reconciliation');
      if (old.length) await notifications.cancel({ notifications: old.map(note => ({ id: note.id })) });
    } catch (_) {}
  }
  if (state.currentView === 'settings') render();
  return true;
}

async function syncNativeSystemBarsTheme() {
  const bars = getCapacitorPlugin('SystemBars');
  if (!bars?.setStyle) return;
  const dark = document.documentElement.classList.contains('dark');
  try { await bars.setStyle({ style: dark ? 'DARK' : 'LIGHT' }); } catch (_) {}
}

async function initializeNativeSessionProtection() {
  await setupNativeServices();
  if (!isPackagedMobileApp() || !state?.currentUser || !_nativePrefs.biometricEnabled) {
    removeNativeAppLock();
    queueNativeReminderSync();
    return true;
  }
  renderNativeAppLock();
  const unlocked = await unlockNativeApp();
  queueNativeReminderSync();
  return unlocked;
}

async function setupNativeServices() {
  if (_nativeServicesPromise) return _nativeServicesPromise;
  _nativeServicesPromise = (async () => {
    setupAdaptiveViewport();
    if (!isPackagedMobileApp()) {
      _nativePrefs.ready = true;
      return;
    }

    _nativePrefs.biometricEnabled = (await nativeSecureGet('biometric_lock_enabled')) === true;
    _nativePrefs.remindersEnabled = (await nativeSecureGet('reconciliation_reminders_enabled')) === true;
    if (typeof hydrateAppLoginPendingFromSecureStorage === 'function') {
      await hydrateAppLoginPendingFromSecureStorage();
    }
    await getNativeBiometricInfo(true);
    _nativePrefs.ready = true;
    if (_nativePrefs.biometricEnabled) renderNativeAppLock();

    const keyboard = getCapacitorPlugin('Keyboard');
    await _addNativeListener(keyboard, 'keyboardWillShow', event => _setNativeKeyboardOpen(true, event?.keyboardHeight));
    await _addNativeListener(keyboard, 'keyboardWillHide', () => _setNativeKeyboardOpen(false, 0));

    const network = getCapacitorPlugin('Network');
    await _addNativeListener(network, 'networkStatusChange', status => {
      if (!status?.connected) showMobileConnectivityNotice({ serverReachable: false });
      else retryMobileConnection().catch(() => showMobileConnectivityNotice({ serverReachable: false }));
    });

    const app = getCapacitorAppPlugin();
    await _addNativeListener(app, 'appStateChange', event => {
      if (!event?.isActive) {
        _nativeBackgroundedAt = Date.now();
        if (_nativePrefs.biometricEnabled && state?.currentUser) renderNativeAppLock();
        return;
      }
      const protectedSession = _nativePrefs.biometricEnabled && state?.currentUser;
      if (protectedSession && Date.now() - _nativeBackgroundedAt >= NATIVE_APP_LOCK_AFTER_MS) {
        renderNativeAppLock();
        unlockNativeApp();
      } else {
        // Keep private data hidden in the app-switcher snapshot, but do not
        // make a quick return wait for biometrics before the lock timeout.
        removeNativeAppLock();
      }
      queueNativeReminderSync();
    });
    await _addNativeListener(app, 'appRestoredResult', event => {
      if (event?.pluginId !== 'Camera' || event?.methodName !== 'getPhoto' || !event?.data) return;
      let pending = null;
      try { pending = JSON.parse(localStorage.getItem(NATIVE_PHOTO_PENDING_KEY) || 'null'); } catch (_) {}
      if (pending?.target) _deliverNativeCameraResult(event.data, pending.target, null);
    });

    const notifications = getCapacitorPlugin('LocalNotifications');
    await _addNativeListener(notifications, 'localNotificationActionPerformed', async action => {
      if (action?.notification?.extra?.albayanType !== 'reconciliation') return;
      if (_nativePrefs.biometricEnabled && state?.currentUser) await unlockNativeApp();
      if (state?.currentUser && typeof navigateToInternal === 'function') navigateToInternal('reconciliation');
    });

    const browser = getCapacitorPlugin('Browser');
    await _addNativeListener(browser, 'browserFinished', () => {
      // Keep the pending PKCE request: the external login may still return
      // through a deep link after the browser view finishes.
      try { if (typeof render === 'function') render(); } catch (_) {}
    });
    await syncNativeSystemBarsTheme();
  })().catch(error => {
    console.warn('[NativeServices] Setup failed:', error?.message || error);
    _nativePrefs.ready = true;
  });
  return _nativeServicesPromise;
}
// ==========================================
// SECURITY MODULE - XSS Protection, Sanitization, Hashing
// ==========================================

const RECORD_IDENTIFIER_FIELDS = new Set([
  'adId', 'customerId', 'creatorId', 'deliveryPersonId', 'driverId',
  'fromUserId', 'fundingReceiptId', 'linkedDeliveryReceiptId', 'linkedReceiptId',
  'orderId', 'pageId', 'paymentTxId', 'productId', 'receiptId', 'referenceId',
  'resourceId', 'serviceId', 'shipmentId', 'targetCustomerId', 'targetUserId',
  'toCustomerId', 'toReceiptId', 'toUserId', 'transactionId',
  'transferFromCustomerId', 'transferFromReceiptId', 'userId'
]);
const RECORD_IDENTIFIER_LIST_FIELDS = new Set(['adReceiptIds', 'customerIds', 'linkedCustomerIds', 'receiptIds']);

// ==========================================
// PURE-JS CRYPTO FALLBACK (insecure contexts)
// ==========================================
// crypto.subtle only exists in secure contexts (https:// or localhost). On a
// plain-HTTP LAN origin (e.g. a phone opening http://192.168.x.x:8000) it is
// undefined in both iOS Safari and Android Chrome, which used to make every
// local-mode password flow throw. These pure-JS SHA-256 / PBKDF2-HMAC-SHA256
// implementations produce byte-identical output to the Web Crypto API and are
// used only when crypto.subtle is unavailable.

// New hashes created on the pure-JS path use fewer iterations (still recorded
// in the stored `iterations` field, so they verify anywhere) because 600k
// PBKDF2 iterations in plain JS would block the UI for many seconds.
const _ALB_FALLBACK_PBKDF2_ITERATIONS = 60000;
// Web Crypto runs off the UI thread and can use OWASP's current
// PBKDF2-HMAC-SHA256 work factor without freezing the browser.
const _ALB_NATIVE_PBKDF2_ITERATIONS = 600000;

// SHA-256 round constants (FIPS 180-4)
const _ALB_SHA256_K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
]);

// Pure-JS SHA-256. Takes a Uint8Array, returns a 32-byte Uint8Array digest
// identical to crypto.subtle.digest('SHA-256', bytes).
function _albFallbackSha256(bytes) {
  const len = bytes.length;
  // Pad to: message + 0x80 + zeros + 64-bit big-endian bit length, multiple of 64 bytes.
  const padded = new Uint8Array(((len + 8) >> 6 << 6) + 64);
  padded.set(bytes);
  padded[len] = 0x80;
  const dv = new DataView(padded.buffer);
  dv.setUint32(padded.length - 8, Math.floor(len / 0x20000000)); // high 32 bits of len*8
  dv.setUint32(padded.length - 4, (len << 3) >>> 0);             // low 32 bits of len*8

  const h = new Uint32Array([
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
  ]);
  const w = new Uint32Array(64);

  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];
      const s0 = (((w15 >>> 7) | (w15 << 25)) ^ ((w15 >>> 18) | (w15 << 14)) ^ (w15 >>> 3)) >>> 0;
      const s1 = (((w2 >>> 17) | (w2 << 15)) ^ ((w2 >>> 19) | (w2 << 13)) ^ (w2 >>> 10)) >>> 0;
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }

    let a = h[0], b = h[1], c = h[2], d = h[3];
    let e = h[4], f = h[5], g = h[6], hh = h[7];
    for (let i = 0; i < 64; i++) {
      const S1 = (((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7))) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (hh + S1 + ch + _ALB_SHA256_K[i] + w[i]) >>> 0;
      const S0 = (((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10))) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h[0] = (h[0] + a) >>> 0; h[1] = (h[1] + b) >>> 0;
    h[2] = (h[2] + c) >>> 0; h[3] = (h[3] + d) >>> 0;
    h[4] = (h[4] + e) >>> 0; h[5] = (h[5] + f) >>> 0;
    h[6] = (h[6] + g) >>> 0; h[7] = (h[7] + hh) >>> 0;
  }

  const out = new Uint8Array(32);
  const outDv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) outDv.setUint32(i * 4, h[i]);
  return out;
}

// Pure-JS PBKDF2-HMAC-SHA256. Takes Uint8Arrays, returns a byteLen-byte
// Uint8Array identical to crypto.subtle.deriveBits({ name: 'PBKDF2', ... }).
function _albFallbackPbkdf2Sha256(passwordBytes, saltBytes, iterations, byteLen) {
  if (!Number.isFinite(iterations) || iterations < 1) throw new Error('Invalid PBKDF2 iterations');

  // HMAC key: keys longer than the 64-byte SHA-256 block are hashed first.
  let key = passwordBytes;
  if (key.length > 64) key = _albFallbackSha256(key);
  const ipad = new Uint8Array(64);
  const opad = new Uint8Array(64);
  for (let i = 0; i < 64; i++) {
    const k = i < key.length ? key[i] : 0;
    ipad[i] = k ^ 0x36;
    opad[i] = k ^ 0x5c;
  }
  const hmac = (msg) => {
    const innerBuf = new Uint8Array(64 + msg.length);
    innerBuf.set(ipad);
    innerBuf.set(msg, 64);
    const inner = _albFallbackSha256(innerBuf);
    const outerBuf = new Uint8Array(96);
    outerBuf.set(opad);
    outerBuf.set(inner, 64);
    return _albFallbackSha256(outerBuf);
  };

  const out = new Uint8Array(byteLen);
  const blocks = Math.ceil(byteLen / 32);
  for (let block = 1; block <= blocks; block++) {
    // U1 = HMAC(password, salt || INT_32_BE(block))
    const msg = new Uint8Array(saltBytes.length + 4);
    msg.set(saltBytes);
    msg[saltBytes.length] = (block >>> 24) & 0xff;
    msg[saltBytes.length + 1] = (block >>> 16) & 0xff;
    msg[saltBytes.length + 2] = (block >>> 8) & 0xff;
    msg[saltBytes.length + 3] = block & 0xff;
    let u = hmac(msg);
    const t = u.slice();
    for (let iter = 1; iter < iterations; iter++) {
      u = hmac(u);
      for (let i = 0; i < 32; i++) t[i] ^= u[i];
    }
    const offset = (block - 1) * 32;
    out.set(t.subarray(0, Math.min(32, byteLen - offset)), offset);
  }
  return out;
}

const Security = {
  // XSS Protection - Escape HTML entities
  escapeHtml: (str) => {
    if (str === null || str === undefined) return '';
    const div = document.createElement('div');
    div.textContent = String(str);
    // textContent -> innerHTML escapes <, >, & (but NOT quotes). We also escape quotes for attribute safety.
    return div.innerHTML
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  },
  
  // Unescape HTML (for display in input fields)
  // XSS-SAFE: Uses textContent extraction (no script execution)
  unescapeHtml: (str) => {
    if (!str) return '';
    const div = document.createElement('div');
    div.innerHTML = str;  // Safe: immediately extract as text
    return div.textContent || div.innerText || '';
  },

  // Return a URL safe to put in an href/src, or '#' for an unsafe scheme.
  // escapeHtml alone does NOT neutralize javascript:/data:/vbscript: URLs, so
  // any user-supplied link (e.g. a customer profile link stored raw) must pass
  // through here before rendering. Allows http/https/mailto/tel and
  // relative / protocol-relative URLs.
  safeUrl: (url) => {
    const s = String(url == null ? '' : url).trim();
    if (!s) return '#';
    // Collapse control chars / whitespace that could hide a scheme like
    // "java\tscript:alert(1)".
    const cleaned = s.replace(/[\u0000-\u0020\u007f]+/g, '');
    if (/^(?:https?:|mailto:|tel:)/i.test(cleaned)) return s;   // known-safe scheme
    if (/^[a-z][a-z0-9+.\-]*:/i.test(cleaned)) return '#';       // any other explicit scheme -> block
    return s;                                                    // no scheme (relative/anchor) -> ok
  },

  // Sanitize input - remove dangerous characters and patterns
  sanitizeInput: (input, options = {}) => {
    if (input === null || input === undefined) return '';
    let str = String(input);
    
    // Remove null bytes
    str = str.replace(/\0/g, '');
    
    // Remove script tags and event handlers if not allowed
    if (!options.allowHtml) {
      str = str.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
      str = str.replace(/on\w+\s*=/gi, '');
      str = str.replace(/javascript:/gi, '');
      if (!options.allowDataUrl) {
        str = str.replace(/data:/gi, '');
      } else {
        // Only allow safe image data URLs; strip any other data: usage
        const trimmed = str.trim();
        if (/^data:/i.test(trimmed)) {
          const isSafeImageDataUrl = /^data:image\/(png|jpe?g|gif|webp);base64,[a-z0-9+/=]+$/i.test(trimmed);
          if (!isSafeImageDataUrl) {
            str = '';
          }
        } else {
          str = str.replace(/data:/gi, '');
        }
      }
      str = str.replace(/vbscript:/gi, '');
      // Remove any remaining angle brackets to prevent HTML/attribute injection
      str = str.replace(/[<>]/g, '');
    }
    
    // Trim whitespace
    str = str.trim();
    
    // Limit length if specified
    if (options.maxLength && str.length > options.maxLength) {
      str = str.substring(0, options.maxLength);
    }
    
    return str;
  },

  // Sanitize object recursively
  sanitizeObject: (obj, depth = 0) => {
    // Never return unsanitized attacker-controlled data when the nesting limit
    // is exceeded. Dropping an over-deep branch fails closed and still protects
    // the UI from recursion/stack exhaustion.
    if (depth > 10) return null;
    if (obj === null || obj === undefined) return obj;
    if (typeof obj === 'string') return Security.sanitizeInput(obj);
    if (typeof obj !== 'object') return obj;
    if (Array.isArray(obj)) {
      return obj.map(item => {
        if (typeof item === 'string' && item.trim().toLowerCase().startsWith('data:image/')) {
          return Security.sanitizeInput(item, { allowDataUrl: true });
        }
        return Security.sanitizeObject(item, depth + 1);
      });
    }
    // Prevent prototype pollution by using null-prototype objects and blocking dangerous keys
    const sanitized = Object.create(null);
    const blockedKeys = new Set(['__proto__', 'prototype', 'constructor']);
    for (const key of Object.keys(obj)) {
      if (blockedKeys.has(key)) continue;
      const sanitizedKey = Security.sanitizeInput(key, { maxLength: 100 });
      if (!sanitizedKey || blockedKeys.has(sanitizedKey)) continue;
      const value = obj[key];
      const looksLikeImageKey = /photo|photos|image|images|screenshot/i.test(String(key));
      if (typeof value === 'string') {
        sanitized[sanitizedKey] = looksLikeImageKey
          ? Security.sanitizeInput(value, { allowDataUrl: true })
          : Security.sanitizeInput(value);
      } else if (Array.isArray(value) && looksLikeImageKey) {
        sanitized[sanitizedKey] = value.map(v => {
          if (typeof v === 'string') return Security.sanitizeInput(v, { allowDataUrl: true });
          return Security.sanitizeObject(v, depth + 1);
        });
      } else {
        sanitized[sanitizedKey] = Security.sanitizeObject(value, depth + 1);
      }
    }
    return sanitized;
  },

  // Internal: bytes <-> hex helpers
  _bytesToHex: (bytes) => Array.from(bytes, b => b.toString(16).padStart(2, '0')).join(''),
  _hexToBytes: (hex) => {
    const clean = String(hex || '').trim();
    if (!clean || clean.length % 2 !== 0 || !/^[0-9a-f]+$/i.test(clean)) {
      throw new Error('Invalid hex salt');
    }
    const bytes = new Uint8Array(clean.length / 2);
    for (let i = 0; i < bytes.length; i++) {
      const byte = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
      if (Number.isNaN(byte)) throw new Error('Invalid hex salt');
      bytes[i] = byte;
    }
    return bytes;
  },

  // Password hashing using Web Crypto API (PBKDF2 by default; legacy SHA-256 supported)
  // Falls back to pure-JS SHA-256/PBKDF2 when crypto.subtle is unavailable
  // (insecure http:// origins) — output is byte-identical either way.
  // Returns: { hash, salt, algo, iterations? }
  hashPassword: async (password, salt = null, options = {}) => {
    const algo = options.algo || 'pbkdf2-sha256';
    const pwd = String(password ?? '');
    const encoder = new TextEncoder();
    // crypto.getRandomValues still works in insecure contexts; only subtle.* is gone.
    const subtle = (globalThis.crypto && globalThis.crypto.subtle) ? globalThis.crypto.subtle : null;

    if (algo === 'sha256') {
      const saltHex = salt
        ? String(salt)
        : Security._bytesToHex(crypto.getRandomValues(new Uint8Array(16)));
      const data = encoder.encode(saltHex + pwd);
      const digest = subtle
        ? new Uint8Array(await subtle.digest('SHA-256', data))
        : _albFallbackSha256(data);
      const hash = Security._bytesToHex(digest);
      return { hash, salt: saltHex, algo: 'sha256' };
    }

    // PBKDF2-SHA256 (recommended). New hashes made on the pure-JS path use a
    // lower default iteration count (recorded in `iterations`, which every
    // call site round-trips through user.passwordIterations, so the hash
    // verifies everywhere — including later under HTTPS with native crypto).
    // Verification always passes the stored count explicitly, so it is never
    // affected by this default.
    const iterations = Number.isFinite(options.iterations)
      ? options.iterations
      : (subtle ? _ALB_NATIVE_PBKDF2_ITERATIONS : _ALB_FALLBACK_PBKDF2_ITERATIONS);
    if (!Number.isSafeInteger(iterations) || iterations < 1 || iterations > 10000000) {
      throw new Error('PBKDF2 iterations are outside the supported range');
    }
    const saltBytes = salt
      ? Security._hexToBytes(salt)
      : crypto.getRandomValues(new Uint8Array(16));
    if (saltBytes.length < 8 || saltBytes.length > 128) {
      throw new Error('Password salt is outside the supported range');
    }
    const saltHex = typeof salt === 'string' ? String(salt) : Security._bytesToHex(saltBytes);

    let derived;
    if (subtle) {
      const keyMaterial = await subtle.importKey(
        'raw',
        encoder.encode(pwd),
        { name: 'PBKDF2' },
        false,
        ['deriveBits']
      );

      const bits = await subtle.deriveBits(
        {
          name: 'PBKDF2',
          salt: saltBytes,
          iterations,
          hash: 'SHA-256'
        },
        keyMaterial,
        256
      );
      derived = new Uint8Array(bits);
    } else {
      derived = _albFallbackPbkdf2Sha256(encoder.encode(pwd), saltBytes, iterations, 32);
    }

    const hash = Security._bytesToHex(derived);
    return { hash, salt: saltHex, algo: 'pbkdf2-sha256', iterations };
  },

  // Verify password against stored hash (supports legacy + PBKDF2)
  verifyPassword: async (password, storedHash, salt, algo = 'sha256', iterations = null) => {
    if (algo !== 'sha256' && algo !== 'pbkdf2-sha256') return false;
    const normalizedHash = String(storedHash || '').trim().toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(normalizedHash)) return false;
    // Backwards compatibility: some backups may store iterations as a numeric string.
    // Example: "310000" instead of 310000. Treat digit-only strings as numbers.
    let iters = iterations;
    if (typeof iters === 'string') {
      const trimmed = iters.trim();
      if (/^[0-9]{1,10}$/.test(trimmed)) {
        const n = Number(trimmed);
        if (Number.isFinite(n)) iters = n;
      }
    }
    // Old local backups created before iteration metadata was added used
    // 310,000 rounds. Preserve that exact verification path, then upgrade the
    // hash to the current work factor after a successful login.
    if (algo === 'pbkdf2-sha256' && !Number.isFinite(iters)) iters = 310000;
    if (algo === 'pbkdf2-sha256' && (
      !Number.isSafeInteger(iters) || iters < 1 || iters > 10000000
    )) return false;
    try {
      const opts = algo === 'pbkdf2-sha256'
        ? { algo: 'pbkdf2-sha256', iterations: iters }
        : { algo: 'sha256' };
      const { hash } = await Security.hashPassword(password, salt, opts);
      // Compare every character to avoid an early-exit password-hash oracle.
      let difference = 0;
      for (let i = 0; i < 64; i++) {
        difference |= hash.charCodeAt(i) ^ normalizedHash.charCodeAt(i);
      }
      return difference === 0;
    } catch (_) {
      return false;
    }
  },

  // Generate secure random ID
  generateSecureId: (prefix = 'id') => {
    const array = new Uint8Array(16);
    crypto.getRandomValues(array);
    const random = Array.from(array, b => b.toString(16).padStart(2, '0')).join('');
    return `${prefix}_${Date.now()}_${random.substring(0, 12)}`;
  },

  // Record identifiers are used in URLs, data-* attributes and (for legacy
  // screens) inline handlers. Keep them deliberately boring so an imported or
  // server-provided id can never break out of one of those contexts. This also
  // matches the backend's 80-character id limit.
  isValidRecordId: (value) => {
    const id = String(value == null ? '' : value).trim();
    return /^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$/.test(id);
  },

  // Validate record ids and relationship ids without rewriting them. Rewriting
  // would silently break links between customers, receipts, ads and users, so
  // callers must reject the whole import/server payload when this fails.
  validateRecordIdentifiers: (value, path = 'record', depth = 0, validateOwnId = depth === 0) => {
    if (depth > 12 || value === null || value === undefined) return { valid: true };
    if (Array.isArray(value)) {
      for (let i = 0; i < value.length; i++) {
        // A top-level array is a collection of records, so each direct child's
        // `id` is a record id. Nested arrays are data inside a record (for
        // example passkeys[].id is an opaque WebAuthn credential and can be
        // much longer than 80 characters), so their generic `id` fields must
        // not be treated as entity identifiers.
        const childOwnId = depth === 0 && validateOwnId;
        const result = Security.validateRecordIdentifiers(value[i], `${path}[${i}]`, depth + 1, childOwnId);
        if (!result.valid) return result;
      }
      return { valid: true };
    }
    if (typeof value !== 'object') return { valid: true };

    for (const [key, child] of Object.entries(value)) {
      const isSingleId = RECORD_IDENTIFIER_FIELDS.has(key) || (key === 'id' && validateOwnId);
      const isIdList = RECORD_IDENTIFIER_LIST_FIELDS.has(key);
      if (isSingleId) {
        const blank = child === null || child === undefined || String(child).trim() === '';
        if (blank && key === 'id') {
          return { valid: false, error: `Missing identifier at ${path}.${key}` };
        }
        if (!blank && (typeof child !== 'string' || !Security.isValidRecordId(child))) {
          return { valid: false, error: `Unsafe identifier at ${path}.${key}` };
        }
      } else if (isIdList && child !== null && child !== undefined) {
        if (!Array.isArray(child)) return { valid: false, error: `Invalid identifier list at ${path}.${key}` };
        for (let i = 0; i < child.length; i++) {
          if (typeof child[i] !== 'string' || !Security.isValidRecordId(child[i])) {
            return { valid: false, error: `Unsafe identifier at ${path}.${key}[${i}]` };
          }
        }
      }

      if (child && typeof child === 'object') {
        const result = Security.validateRecordIdentifiers(child, `${path}.${key}`, depth + 1, false);
        if (!result.valid) return result;
      }
    }
    return { valid: true };
  },

  // Validate email format
  isValidEmail: (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  },

  // Validate phone format (basic)
  isValidPhone: (phone) => {
    const cleaned = phone.replace(/[\s\-\(\)]/g, '');
    return /^\+?[\d]{7,15}$/.test(cleaned);
  },

  // Rate limiting for login attempts
  loginAttempts: new Map(),
  
  checkRateLimit: (identifier, maxAttempts = LIMIT_CONSTANTS.MAX_RATE_LIMIT_ATTEMPTS, windowMs = TIME_CONSTANTS.RATE_LIMIT_WINDOW_MINUTES * TIME_CONSTANTS.MILLISECONDS_PER_MINUTE) => {
    const now = Date.now();
    const attempts = Security.loginAttempts.get(identifier) || [];
    
    // Filter out old attempts
    const recentAttempts = attempts.filter(time => now - time < windowMs);
    
    if (recentAttempts.length >= maxAttempts) {
      const oldestAttempt = Math.min(...recentAttempts);
      const waitTime = Math.ceil((windowMs - (now - oldestAttempt)) / 1000 / 60);
      return { allowed: false, waitMinutes: waitTime };
    }
    
    return { allowed: true };
  },

  recordLoginAttempt: (identifier) => {
    const now = Date.now();
    const windowMs = TIME_CONSTANTS.RATE_LIMIT_WINDOW_MINUTES * TIME_CONSTANTS.MILLISECONDS_PER_MINUTE;
    const attempts = Security.loginAttempts.get(identifier) || [];
    // Filter out old attempts before adding new one (prevents unbounded growth)
    const recentAttempts = attempts.filter(time => now - time < windowMs);
    recentAttempts.push(now);
    Security.loginAttempts.set(identifier, recentAttempts);

    // Periodically clean up old entries from the map (every 100 attempts)
    if (Math.random() < 0.01) {
      Security._cleanupOldAttempts(windowMs);
    }
  },

  clearLoginAttempts: (identifier) => {
    Security.loginAttempts.delete(identifier);
  },

  // Clean up old entries from the login attempts map to prevent memory leaks
  _cleanupOldAttempts: (windowMs) => {
    const now = Date.now();
    for (const [identifier, attempts] of Security.loginAttempts.entries()) {
      const recentAttempts = attempts.filter(time => now - time < windowMs);
      if (recentAttempts.length === 0) {
        Security.loginAttempts.delete(identifier);
      } else {
        Security.loginAttempts.set(identifier, recentAttempts);
      }
    }
  },

  // Safe HTML builder - prevents XSS by escaping all dynamic content
  safeHTML: (strings, ...values) => {
    return strings.reduce((result, str, i) => {
      const value = values[i - 1];
      const escapedValue = value !== undefined ? Security.escapeHtml(String(value)) : '';
      return result + escapedValue + str;
    });
  },

  // Create safe element with escaped text content
  createSafeElement: (tag, textContent, attributes = {}) => {
    const element = document.createElement(tag);
    element.textContent = textContent; // textContent is automatically escaped
    for (const [key, value] of Object.entries(attributes)) {
      // Only allow safe attributes
      const safeAttrs = ['id', 'class', 'style', 'type', 'name', 'value', 'placeholder', 'disabled', 'readonly', 'data-id'];
      if (safeAttrs.includes(key) || key.startsWith('data-')) {
        element.setAttribute(key, Security.sanitizeInput(value));
      }
    }
    return element;
  },

  // Validate that data hasn't been tampered with
  validateDataIntegrity: (data, expectedChecksum) => {
    const currentChecksum = DataIntegrity.calculateChecksum(data);
    return currentChecksum === expectedChecksum;
  }
};

// ==========================================
// DEBUG MODE: Conditional debug telemetry (disabled in production)
// ==========================================
// Debug telemetry can only be enabled from a local development origin. A
// production URL parameter must never make customer/accounting data eligible
// for diagnostic logging.

const ALBAYAN_DEBUG_MODE = (() => {
  try {
    const host = String(window.location.hostname || '').toLowerCase();
    const isLocalDevelopment = host === 'localhost' || host === '127.0.0.1' || host === '::1';
    if (!isLocalDevelopment) return false;
    // Check URL param for explicit local debug mode
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('debug') === '1') return true;
    // Default: debug mode is off in production
    return false;
  } catch (_) {
    return false;
  }
})();

// No-op debug emit function (used throughout codebase)
window.__albayanDebugEmit = ALBAYAN_DEBUG_MODE 
  ? (hypothesisId, location, message, data) => {
      try {
        const payload = {
          sessionId: 'debug-session',
          runId: 'audit-pre',
          hypothesisId: String(hypothesisId || '').slice(0, 32),
          location: String(location || '').slice(0, 180),
          message: String(message || '').slice(0, 240),
          data: (data && typeof data === 'object') ? data : {},
          timestamp: Date.now(),
        };
        fetch('/api/_debug/telemetry', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        }).catch(() => {});
      } catch (_) {}
    }
  : () => {}; // No-op in production

// ==========================================
// DATA ISOLATION - Prevent cross-feature data corruption
// ==========================================

const DataIsolation = {
  // Wrap data operations in isolated context
  isolatedOperation: (collectionName, operation) => {
    try {
      // Create a copy of the collection for isolated operation
      const collection = state[collectionName];
      if (!Array.isArray(collection)) {
        throw new Error(`Invalid collection: ${collectionName}`);
      }
      
      // Perform operation on copy first
      const result = operation([...collection]);
      
      // Validate result before applying
      if (result !== undefined && Array.isArray(result)) {
        // Verify no invalid data was introduced
        for (const item of result) {
          if (typeof item !== 'object' || item === null) {
            throw new Error('Invalid item in result');
          }
        }
        return result;
      }
      return collection;
    } catch (error) {
      console.error(`Isolated operation failed for ${collectionName}:`, error);
      addSecurityLog('data_isolation_error', `${collectionName}: ${error.message}`);
      throw error;
    }
  },

  // Safe record access with bounds checking
  safeGetRecord: (collection, id) => {
    if (!Array.isArray(collection)) return null;
    const record = collection.find(item => item && item.id === id);
    return record ? { ...record } : null; // Return copy, not reference
  },

  // Safe record update with validation
  safeUpdateRecord: (collectionName, id, updates) => {
    const collection = state[collectionName];
    if (!Array.isArray(collection)) return false;
    
    const index = collection.findIndex(item => item && item.id === id);
    if (index === -1) return false;
    
    // Sanitize updates
    const sanitizedUpdates = Security.sanitizeObject(updates);
    
    // Preserve critical fields
    const protectedFields = ['id', '_created', 'createdBy'];
    for (const field of protectedFields) {
      if (sanitizedUpdates[field] !== undefined && 
          collection[index][field] !== undefined &&
          sanitizedUpdates[field] !== collection[index][field]) {
        delete sanitizedUpdates[field]; // Don't allow changing protected fields
      }
    }
    
    collection[index] = { 
      ...collection[index], 
      ...sanitizedUpdates, 
      _lastModified: Date.now() 
    };
    
    return true;
  },

  // Validate collection integrity
  validateCollection: (collectionName) => {
    const collection = state[collectionName];
    if (!Array.isArray(collection)) return { valid: false, errors: ['Not an array'] };
    
    const errors = [];
    const ids = new Set();
    
    collection.forEach((item, index) => {
      if (!item || typeof item !== 'object') {
        errors.push(`Invalid item at index ${index}`);
        return;
      }
      
      if (!item.id) {
        errors.push(`Missing ID at index ${index}`);
      } else if (ids.has(item.id)) {
        errors.push(`Duplicate ID: ${item.id}`);
      } else {
        ids.add(item.id);
      }
    });
    
    return { valid: errors.length === 0, errors };
  }
};

// ==========================================
// SESSION MANAGEMENT - Secure session handling
// ==========================================

// iOS Safari with "Block All Cookies" (and Chrome/Android with cookies
// blocked for the site) makes ANY window.sessionStorage access throw a
// SecurityError. Local-mode login calls createSession AFTER the password is
// already verified, so an unguarded throw made login impossible with a
// misleading generic error. Fall back to a page-lifetime in-memory session.
let _memorySession = null;

const SessionManager = {
  SESSION_DURATION: 8 * 60 * 60 * 1000, // 8 hours
  SESSION_KEY: 'albayan_session',

  createSession: (userId) => {
    const session = {
      userId,
      createdAt: Date.now(),
      expiresAt: Date.now() + SessionManager.SESSION_DURATION,
      token: Security.generateSecureId('session')
    };
    try {
      sessionStorage.setItem(SessionManager.SESSION_KEY, JSON.stringify(session));
    } catch (_) {
      _memorySession = session;
    }
    return session;
  },

  getSession: () => {
    try {
      const sessionStr = sessionStorage.getItem(SessionManager.SESSION_KEY);
      const session = sessionStr ? JSON.parse(sessionStr) : _memorySession;
      if (!session) return null;

      // Check if session is expired
      if (Date.now() > session.expiresAt) {
        SessionManager.destroySession();
        return null;
      }

      return session;
    } catch (e) {
      // Storage blocked (throw-on-read): honor the in-memory fallback.
      return _memorySession && Date.now() <= _memorySession.expiresAt ? _memorySession : null;
    }
  },

  refreshSession: () => {
    const session = SessionManager.getSession();
    if (session) {
      session.expiresAt = Date.now() + SessionManager.SESSION_DURATION;
      try {
        sessionStorage.setItem(SessionManager.SESSION_KEY, JSON.stringify(session));
      } catch (_) {
        _memorySession = session;
      }
    }
  },

  destroySession: () => {
    _memorySession = null;
    try { sessionStorage.removeItem(SessionManager.SESSION_KEY); } catch (_) {}
  },

  isAuthenticated: () => {
    return SessionManager.getSession() !== null;
  }
};

// ==========================================
// DATA INTEGRITY - Checksum and validation
// ==========================================

const DataIntegrity = {
  // Calculate simple checksum for data integrity
  calculateChecksum: (data) => {
    const str = JSON.stringify(data);
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32bit integer
    }
    return Math.abs(hash).toString(16);
  },

  // Validate data structure
  validateDataStructure: (data, schema) => {
    const errors = [];
    
    for (const [key, rules] of Object.entries(schema)) {
      const value = data[key];
      
      if (rules.required && (value === undefined || value === null || value === '')) {
        errors.push(`${key} is required`);
        continue;
      }
      
      if (value !== undefined && value !== null) {
        if (rules.type === 'string' && typeof value !== 'string') {
          errors.push(`${key} must be a string`);
        }
        if (rules.type === 'number' && typeof value !== 'number') {
          errors.push(`${key} must be a number`);
        }
        if (rules.type === 'array' && !Array.isArray(value)) {
          errors.push(`${key} must be an array`);
        }
        if (rules.maxLength && typeof value === 'string' && value.length > rules.maxLength) {
          errors.push(`${key} exceeds maximum length of ${rules.maxLength}`);
        }
        if (rules.min !== undefined && typeof value === 'number' && value < rules.min) {
          errors.push(`${key} must be at least ${rules.min}`);
        }
        if (rules.max !== undefined && typeof value === 'number' && value > rules.max) {
          errors.push(`${key} must be at most ${rules.max}`);
        }
      }
    }
    
    return { valid: errors.length === 0, errors };
  },

  // Freeze object to prevent modification
  freezeData: (obj) => {
    if (typeof obj !== 'object' || obj === null) return obj;
    Object.freeze(obj);
    Object.keys(obj).forEach(key => {
      if (typeof obj[key] === 'object' && obj[key] !== null) {
        DataIntegrity.freezeData(obj[key]);
      }
    });
    return obj;
  }
};

// ==========================================
// NUMBER PARSING UTILITIES - Strict validation
// ==========================================

/**
 * Parse a value to a number with strict validation.
 * Unlike parseFloat("123abc") which returns 123, this returns NaN for invalid input.
 * 
 * @param {any} value - Value to parse
 * @param {object} options - Optional configuration
 * @param {number} options.min - Minimum allowed value (returns NaN if below)
 * @param {number} options.max - Maximum allowed value (returns NaN if above)
 * @param {number} options.defaultValue - Value to return if parsing fails (default: NaN)
 * @returns {number} Parsed number or defaultValue if invalid
 */
function strictParseNumber(value, options = {}) {
  const { min, max, defaultValue = NaN } = options;
  
  // Handle null/undefined
  if (value === null || value === undefined || value === '') {
    return defaultValue;
  }
  
  // If already a number
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return defaultValue;
    if (min !== undefined && value < min) return defaultValue;
    if (max !== undefined && value > max) return defaultValue;
    return value;
  }
  
  // Strict string parsing - the entire string must be a valid number
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed === '') return defaultValue;
    
    // Check if string is a valid number format (including scientific notation)
    // This is stricter than parseFloat - it rejects "123abc"
    if (!/^-?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/.test(trimmed)) {
      return defaultValue;
    }
    
    const num = Number(trimmed);
    if (!Number.isFinite(num)) return defaultValue;
    if (min !== undefined && num < min) return defaultValue;
    if (max !== undefined && num > max) return defaultValue;
    return num;
  }
  
  return defaultValue;
}
// ==========================================
// LARGE DATA STORAGE - IndexedDB for big datasets
// ==========================================

const DB_NAME = 'AlbayanDB';
/**
 * IndexedDB Schema Version History
 * ---------------------------------
 * v1: Initial schema (auditLogs, appData stores)
 * v2: Added backups store for auto-backup feature
 * 
 * IMPORTANT: Increment DB_VERSION when:
 * - Adding new object stores
 * - Adding new indexes
 * - Changing key paths
 * 
 * The onupgradeneeded handler MUST handle upgrading from any previous version.
 */
const DB_VERSION = 2;
const LOG_STORE_NAME = 'auditLogs';
const DATA_STORE_NAME = 'appData';
const BACKUP_STORE_NAME = 'backups';

// Storage quotas and limits
const STORAGE_CONFIG = {
  MAX_RECORDS_PER_COLLECTION: 100000, // 100k records per type
  MAX_LOCALSTORAGE_MB: 4,
  BACKUP_RETENTION_DAYS: 30,
  AUTO_BACKUP_INTERVAL: 24 * 60 * 60 * 1000, // Daily
  CHUNK_SIZE: 1000 // Records per chunk for large operations
};

// BEST PRACTICE: Extract magic numbers to named constants for better maintainability
const TIME_CONSTANTS = {
  MILLISECONDS_PER_SECOND: 1000,
  SECONDS_PER_MINUTE: 60,
  MINUTES_PER_HOUR: 60,
  HOURS_PER_DAY: 24,
  MILLISECONDS_PER_MINUTE: 60 * 1000,
  MILLISECONDS_PER_HOUR: 60 * 60 * 1000,
  MILLISECONDS_PER_DAY: 24 * 60 * 60 * 1000,
  SESSION_DURATION_HOURS: 8,
  RATE_LIMIT_WINDOW_MINUTES: 15,
  API_TIMEOUT_MS: 15000,
  API_TIMEOUT_LONG_MS: 20000,
  WEBAUTHN_TIMEOUT_MS: 60000
};

const LIMIT_CONSTANTS = {
  MAX_SECURITY_LOGS: 1000,
  MAX_RATE_LIMIT_ATTEMPTS: 5,
  MAX_PAYMENT_METHODS: 50, // Reasonable limit
  MAX_PHONE_NUMBERS: 10, // Per customer
  MAX_PROFILE_LINKS: 10 // Per customer
};

let db = null;

// Business-data caches are isolated by workspace + authenticated user. Local
// mode keeps the historical unscoped keys so existing single-device data is
// preserved. Server mode activates a different scope only AFTER /api/auth/me
// or login has identified the user, so pre-auth startup can never render the
// previous user's cached customers, receipts or wallet rows.
let _collectionStorageScope = 'local';

function _hashStorageScope(value) {
  const input = String(value || '');
  let hash = 2166136261;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function setCollectionStorageScope(scope) {
  const next = String(scope || 'server:anonymous');
  if (next === _collectionStorageScope) return next;
  _collectionStorageScope = next;
  _corruptedCollections.clear();
  // A debounced write created for user A must not run after user B's scope is
  // activated. In-flight IDB writes capture their keys below and remain safe.
  try {
    if (typeof resetDirtyCollectionQueueForScopeChange === 'function') {
      resetDirtyCollectionQueueForScopeChange();
    }
  } catch (_) {}
  return next;
}

function activateLocalCollectionStorage() {
  return setCollectionStorageScope('local');
}

function activateAnonymousServerCollectionStorage() {
  return setCollectionStorageScope('server:anonymous');
}

function activateServerCollectionStorage(user) {
  const userId = String(user?.id || '').trim();
  if (!Security.isValidRecordId(userId)) throw new Error('Cannot activate cache: invalid authenticated user id');
  let serverIdentity = '';
  try {
    serverIdentity = (typeof getServerBaseUrl === 'function' && getServerBaseUrl()) || window.location?.origin || 'server';
  } catch (_) {
    serverIdentity = 'server';
  }
  return setCollectionStorageScope(`server:${_hashStorageScope(String(serverIdentity).toLowerCase())}:${userId}`);
}

function getCollectionStorageScope() {
  return _collectionStorageScope;
}

function _scopedCollectionStorageName(collectionName, capturedScope = _collectionStorageScope) {
  const name = String(collectionName || '');
  return capturedScope === 'local' ? name : `${capturedScope}:${name}`;
}

/**
 * Initialize IndexedDB for large data storage and caching.
 * Creates necessary object stores and handles version upgrades.
 * Falls back gracefully if IndexedDB is not supported.
 *
 * @param {Function} [onLateOpen] - Adoption callback for an open that succeeds
 *   AFTER this promise already resolved null (watchdog / onblocked). Passing it
 *   means "adopt the late connection AND recover": the callback must re-persist
 *   the authoritative in-memory state (the onclose reopen path does this via
 *   markAllCollectionsDirty() + saveState()). Without it a late connection is
 *   closed and `db` stays null — required at startup, where the collections
 *   were already loaded WITHOUT IndexedDB and flushing them would overwrite
 *   the intact stored copies.
 * @returns {Promise<IDBDatabase|null>} Promise resolving to database instance or null if unsupported
 */
function initIndexedDB(onLateOpen) {
  return new Promise((resolve) => {
    if (!window.indexedDB) {
      console.warn('IndexedDB not supported, falling back to localStorage');
      resolve(null);
      return;
    }

    // RESILIENCE: this promise must ALWAYS settle and can NEVER reject —
    // init() awaits it before the first render, so a hung or failed open
    // would strand the user on the loading screen forever. Known hangs:
    // Safari 14.1–15.x can drop the open request without firing any event,
    // and a DB_VERSION bump in another tab leaves this request in the
    // (previously unhandled) "blocked" state.
    let settled = false;
    let timer = null;
    const done = (val) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(val);
    };

    // Watchdog: if no event ever arrives, continue without IndexedDB.
    // This outcome is INCONCLUSIVE — the store may hold an intact workspace
    // that simply could not be read this session — so flag it for init() /
    // render(), which must not present the workspace as a fresh install.
    // A connection that arrives AFTER this fires is NOT silently adopted
    // (that used to flip saveState() into drop-collections mode and let the
    // next flush overwrite the intact IndexedDB data): see the case split in
    // request.onsuccess below.
    timer = setTimeout(() => {
      console.warn('IndexedDB open timed out, continuing without it');
      window.__albayanIdbOpenInconclusive = true;
      done(null);
    }, 3000);

    let request;
    try {
      request = indexedDB.open(DB_NAME, DB_VERSION);
    } catch (e) {
      // Chrome throws a synchronous SecurityError when site data is blocked.
      console.warn('IndexedDB unavailable:', e);
      done(null);
      return;
    }

    request.onerror = (event) => {
      console.error('IndexedDB error:', event.target.error);
      done(null);
    };

    // Another tab still holds a connection at an older schema version.
    // Fall back to localStorage mode instead of hanging forever. Like the
    // watchdog, this is inconclusive: the stored data itself is intact.
    request.onblocked = () => {
      console.warn('IndexedDB open blocked by another tab');
      window.__albayanIdbOpenInconclusive = true;
      done(null);
    };

    request.onsuccess = (event) => {
      const database = event.target.result;
      // LATE OPEN (the watchdog or onblocked already resolved this promise
      // with null): adopting the connection is only safe when the caller can
      // recover, because `db` truthiness makes saveState() drop the business
      // collections from the localStorage snapshot and re-enables the dirty
      // flush — with in-memory arrays that were loaded WITHOUT IndexedDB.
      // At startup (no onLateOpen) close the connection and stay in the
      // db === null snapshot mode for the whole session; the intact
      // IndexedDB dataset survives untouched until the next reload. The
      // onclose reopen path passes a recovery callback instead: there the
      // in-memory state IS authoritative, so adopt and re-persist it.
      if (settled && typeof onLateOpen !== 'function') {
        try { database.close(); } catch (_) {}
        return;
      }
      db = database;
      window.__albayanIdbOpenInconclusive = false;
      // Let a future DB_VERSION bump in another tab proceed instead of being
      // blocked forever. Closing mid-session degrades gracefully: every idb*
      // helper guards `if (!db)` per call.
      database.onversionchange = () => {
        try { database.close(); } catch (_) {}
        if (db === database) db = null;
      };
      // iOS Safari force-closes the connection when the tab is backgrounded
      // or the device is locked ("Connection to Indexed Database server
      // lost"). Null the handle immediately — saveState() then keeps the
      // business collections inside the localStorage snapshot — and try to
      // reopen; a successful reopen re-persists everything to IndexedDB via
      // the normal dirty-flush machinery.
      database.onclose = () => {
        if (db !== database) return; // a newer connection already took over
        db = null;
        // Recovery runs whether the reopen settles in time (then branch) or
        // arrives late after its own watchdog (onLateOpen inside onsuccess):
        // edits made during the db === null window live only in the
        // localStorage snapshot, so everything must be marked dirty and
        // re-persisted the moment a connection is adopted — otherwise the
        // next saveState() would strip the collections from the snapshot
        // while IndexedDB still holds the pre-close data.
        const recover = () => {
          if (typeof markAllCollectionsDirty === 'function') {
            markAllCollectionsDirty();
            saveState();
          }
        };
        initIndexedDB(recover).then((reopened) => {
          if (reopened) recover();
        }).catch(() => {});
      };
      if (settled) {
        // Late adoption (onclose reopen path only): re-persist before anyone
        // can observe the truthy `db` and skip collections in saveState().
        try { onLateOpen(); } catch (_) {}
      }
      done(database);
    };

    request.onupgradeneeded = (event) => {
      const database = event.target.result;
      
      // Create audit logs store with indexes for efficient querying
      if (!database.objectStoreNames.contains(LOG_STORE_NAME)) {
        const logStore = database.createObjectStore(LOG_STORE_NAME, { keyPath: 'id' });
        logStore.createIndex('date', 'date', { unique: false });
        logStore.createIndex('userId', 'userId', { unique: false });
        logStore.createIndex('action', 'action', { unique: false });
        logStore.createIndex('category', 'category', { unique: false });
        logStore.createIndex('severity', 'severity', { unique: false });
        logStore.createIndex('resourceType', 'resourceType', { unique: false });
      }
      
      // Create main data store for large datasets
      if (!database.objectStoreNames.contains(DATA_STORE_NAME)) {
        const dataStore = database.createObjectStore(DATA_STORE_NAME, { keyPath: 'key' });
        dataStore.createIndex('type', 'type', { unique: false });
        dataStore.createIndex('updatedAt', 'updatedAt', { unique: false });
      }
      
      // Create backup store
      if (!database.objectStoreNames.contains(BACKUP_STORE_NAME)) {
        const backupStore = database.createObjectStore(BACKUP_STORE_NAME, { keyPath: 'id' });
        backupStore.createIndex('createdAt', 'createdAt', { unique: false });
      }
    };
  });
}

// ==========================================
// LARGE DATA OPERATIONS - Store big datasets in IndexedDB
// ==========================================

// BEST PRACTICE: Transaction queue to prevent race conditions in IndexedDB
let idbTransactionQueue = [];
let idbTransactionInProgress = false;

async function processIdbQueue() {
  if (idbTransactionInProgress || idbTransactionQueue.length === 0) return;
  
  idbTransactionInProgress = true;
  while (idbTransactionQueue.length > 0) {
    const task = idbTransactionQueue.shift();
    try {
      await task();
    } catch (error) {
      console.error('IndexedDB queue task error:', error);
    }
  }
  idbTransactionInProgress = false;
}

/**
 * Retrieve a value from IndexedDB by key.
 *
 * @param {string} storeName - Name of the object store
 * @param {string} key - Key to retrieve
 * @returns {Promise<any>} Promise resolving to the stored value or null if not found
 */
function idbGet(storeName, key) {
  if (!db) return Promise.resolve(null);
  return new Promise((resolve, reject) => {
    try {
      const tx = db.transaction([storeName], 'readonly');
      const store = tx.objectStore(storeName);
      const req = store.get(key);
      req.onsuccess = () => resolve(req.result ?? null);
      req.onerror = () => reject(req.error);
    } catch (e) {
      reject(e);
    }
  });
}

/**
 * Store a value in IndexedDB.
 * BEST PRACTICE: Queued to prevent race conditions from concurrent writes.
 *
 * @param {string} storeName - Name of the object store
 * @param {any} value - Value to store (must have an 'id' property)
 * @returns {Promise<void>} Promise resolving when storage is complete
 */
function idbPut(storeName, value) {
  if (!db) return Promise.resolve(false);
  return new Promise((resolve, reject) => {
    const task = () => {
      return new Promise((innerResolve, innerReject) => {
        try {
          const tx = db.transaction([storeName], 'readwrite');
          const store = tx.objectStore(storeName);
          const req = store.put(value);
          req.onsuccess = () => innerResolve(true);
          req.onerror = () => innerReject(req.error);
        } catch (e) {
          innerReject(e);
        }
      });
    };
    
    // BEST PRACTICE: Queue write operations to prevent race conditions
    idbTransactionQueue.push(() => task().then(resolve).catch(reject));
    processIdbQueue();
  });
}

function idbDelete(storeName, key) {
  if (!db) return Promise.resolve(false);
  return new Promise((resolve, reject) => {
    try {
      const tx = db.transaction([storeName], 'readwrite');
      const store = tx.objectStore(storeName);
      const req = store.delete(key);
      req.onsuccess = () => resolve(true);
      req.onerror = () => reject(req.error);
    } catch (e) {
      reject(e);
    }
  });
}

/**
 * Perform several puts and deletes in ONE IndexedDB transaction, atomically.
 * Either every operation commits or none does — so an interrupted collection
 * save (tab close / crash / quota) can never leave new chunks mixed with old
 * ones under a stale meta record (which silently corrupts the collection).
 * Enqueued on the same write queue to preserve serialization. Do NOT await
 * anything between the put/delete calls — an intervening await would let the
 * transaction auto-commit early and defeat atomicity.
 *
 * @param {Array<object>} puts - records to store (each has a `key`)
 * @param {Array<string>} deleteKeys - keys to delete
 * @returns {Promise<boolean>}
 */
function idbAtomicWrite(puts, deleteKeys) {
  if (!db) return Promise.resolve(false);
  return new Promise((resolve, reject) => {
    const task = () => new Promise((innerResolve, innerReject) => {
      try {
        const tx = db.transaction([DATA_STORE_NAME], 'readwrite');
        const store = tx.objectStore(DATA_STORE_NAME);
        tx.oncomplete = () => innerResolve(true);
        tx.onerror = () => innerReject(tx.error);
        tx.onabort = () => innerReject(tx.error || new Error('IndexedDB transaction aborted'));
        for (const v of (puts || [])) store.put(v);
        for (const k of (deleteKeys || [])) store.delete(k);
      } catch (e) {
        innerReject(e);
      }
    });
    idbTransactionQueue.push(() => task().then(resolve).catch(reject));
    processIdbQueue();
  });
}

function idbClear(storeName) {
  if (!db) return Promise.resolve(false);
  return new Promise((resolve, reject) => {
    try {
      const tx = db.transaction([storeName], 'readwrite');
      const store = tx.objectStore(storeName);
      const req = store.clear();
      req.onsuccess = () => resolve(true);
      req.onerror = () => reject(req.error);
    } catch (e) {
      reject(e);
    }
  });
}

function getCollectionMetaKey(collectionName, capturedScope = _collectionStorageScope) {
  return `collection:${_scopedCollectionStorageName(collectionName, capturedScope)}:meta`;
}

function getCollectionChunkKey(collectionName, index, capturedScope = _collectionStorageScope) {
  return `collection:${_scopedCollectionStorageName(collectionName, capturedScope)}:chunk:${index}`;
}

/**
 * Save a large collection to IndexedDB by chunking it into smaller pieces.
 * Uses metadata and chunked storage for efficient retrieval.
 *
 * @param {string} collectionName - Name of the collection (e.g., 'customers', 'ads')
 * @param {Array} data - Array of items to store
 * @returns {Promise<void>} Promise resolving when all chunks are saved
 */
async function saveCollectionToIndexedDB(collectionName, data) {
  if (!db) return false;
  // MULTI-TAB SAFETY: a tab that lost the single-writer lock must never
  // rewrite a collection from its (possibly stale) in-memory array — that
  // would silently delete records the winning tab already persisted.
  if (typeof isAnotherTabWriter === 'function' && isAnotherTabWriter()) return false;
  const name = String(collectionName || '');
  if (!name) return false;
  // Capture the scope before the first await. A logout/login during the write
  // cannot redirect later chunks into a different user's namespace.
  const capturedScope = _collectionStorageScope;
  const dataKey = _scopedCollectionStorageName(name, capturedScope);

  try {
    const metaKey = getCollectionMetaKey(name, capturedScope);
    const prevMeta = await idbGet(DATA_STORE_NAME, metaKey);
    const prevChunkCount = prevMeta?.chunkCount || 0;

    // Small payload -> single record (backwards compatible)
    const isArray = Array.isArray(data);
    const recordCount = isArray ? data.length : 0;
    if (!isArray || recordCount <= STORAGE_CONFIG.CHUNK_SIZE) {
      const record = {
        key: dataKey,
        type: 'collection',
        data,
        checksum: DataIntegrity.calculateChecksum(data),
        updatedAt: Date.now(),
        recordCount
      };

      // Atomic: write the single record AND drop any old chunked layout in one
      // transaction, so we can never end up with both present (which would make
      // load prefer the stale chunked copy).
      const deleteKeys = [];
      if (prevChunkCount > 0) {
        for (let i = 0; i < prevChunkCount; i++) deleteKeys.push(getCollectionChunkKey(name, i, capturedScope));
        deleteKeys.push(metaKey);
      }
      await idbAtomicWrite([record], deleteKeys);
      return true;
    }

    // Large payload -> chunked
    const chunkSize = STORAGE_CONFIG.CHUNK_SIZE;
    const chunkCount = Math.ceil(recordCount / chunkSize);
    const updatedAt = Date.now();

    // Build every chunk record + the meta record, then commit them together
    // with the cleanup deletes in ONE atomic transaction. An interrupted save
    // now rolls back entirely, leaving the previous consistent generation
    // (chunks + meta) intact instead of a corrupt mix.
    const puts = [];
    for (let i = 0; i < chunkCount; i++) {
      const chunk = data.slice(i * chunkSize, (i + 1) * chunkSize);
      puts.push({
        key: getCollectionChunkKey(name, i, capturedScope),
        type: 'collection_chunk',
        collection: name,
        index: i,
        updatedAt,
        data: chunk
      });
    }
    puts.push({
      key: metaKey,
      type: 'collection_meta',
      collection: name,
      chunkSize,
      chunkCount,
      recordCount,
      checksum: DataIntegrity.calculateChecksum(data),
      updatedAt
    });

    const deleteKeys = [];
    // Leftover old chunks beyond the new count
    if (prevChunkCount > chunkCount) {
      for (let i = chunkCount; i < prevChunkCount; i++) deleteKeys.push(getCollectionChunkKey(name, i, capturedScope));
    }
    // Legacy single-record storage, if it exists
    deleteKeys.push(dataKey);

    await idbAtomicWrite(puts, deleteKeys);
    return true;
  } catch (error) {
    console.error('Error saving collection to IndexedDB:', error);
    return false;
  }
}

// DATA SAFETY: collections whose IndexedDB copy loaded INCOMPLETE (a chunk was
// missing / the record count didn't match). Such a collection must never be
// re-saved, or the truncated in-memory array would overwrite the intact-but-
// unread chunks and permanently destroy the missing records.
let _corruptedCollections = new Set();
function isCollectionCorrupted(name) { return _corruptedCollections.has(String(name || '')); }
function markCollectionCorrupted(name) { _corruptedCollections.add(String(name || '')); }
function clearCollectionCorruption(name) { _corruptedCollections.delete(String(name || '')); }

async function loadCollectionFromIndexedDB(collectionName) {
  if (!db) return null;
  const name = String(collectionName || '');
  if (!name) return null;
  const capturedScope = _collectionStorageScope;
  const dataKey = _scopedCollectionStorageName(name, capturedScope);

  try {
    const metaKey = getCollectionMetaKey(name, capturedScope);
    const meta = await idbGet(DATA_STORE_NAME, metaKey);

    // Chunked layout
    if (meta && meta.type === 'collection_meta' && Number.isFinite(meta.chunkCount)) {
      const chunks = [];
      let missingChunk = false;
      for (let i = 0; i < meta.chunkCount; i++) {
        const chunk = await idbGet(DATA_STORE_NAME, getCollectionChunkKey(name, i, capturedScope));
        if (chunk && Array.isArray(chunk.data)) {
          chunks.push(...chunk.data);
        } else {
          console.warn(`Missing chunk for ${name} index ${i}`);
          missingChunk = true;
        }
      }

      let checksumMismatch = false;
      if (meta.checksum) {
        const currentChecksum = DataIntegrity.calculateChecksum(chunks);
        if (currentChecksum !== meta.checksum) {
          console.warn(`Data integrity warning for ${name}: checksum mismatch`);
          checksumMismatch = true;
        }
      }

      // A missing chunk, or a loaded record-count that doesn't match what was
      // saved, means the data we could read is INCOMPLETE. Returning it as if
      // complete would let the caller adopt a truncated collection and re-save
      // it, wiping the unread records. Flag corruption (blocks re-save) and
      // throw so the loader can fall back / warn instead of silently truncating.
      // A checksum mismatch with all chunks present AND a matching record count
      // is treated as a soft warning only (avoids false positives from checksum
      // nuances bricking otherwise-complete data).
      const recordCountMismatch = Number.isFinite(meta.recordCount) && chunks.length !== meta.recordCount;
      if (missingChunk || recordCountMismatch || (checksumMismatch && recordCountMismatch)) {
        markCollectionCorrupted(name);
        const err = new Error(`IndexedDB collection "${name}" is incomplete (${missingChunk ? 'missing chunk' : 'record count mismatch'})`);
        err.code = 'IDB_COLLECTION_CORRUPT';
        err.partialData = chunks;
        throw err;
      }

      return chunks;
    }

    // Legacy single-record layout
    const record = await idbGet(DATA_STORE_NAME, dataKey);
    if (record) {
      const currentChecksum = DataIntegrity.calculateChecksum(record.data);
      if (record.checksum && currentChecksum !== record.checksum) {
        console.warn(`Data integrity warning for ${name}: checksum mismatch`);
      }
      return record.data ?? null;
    }

    return null;
  } catch (error) {
    // Let the corruption signal reach the loader so it can fall back + warn.
    if (error && error.code === 'IDB_COLLECTION_CORRUPT') throw error;
    console.error('Error loading collection from IndexedDB:', error);
    return null;
  }
}

async function createAutoBackup() {
  if (!db) return false;
  
  return new Promise((resolve) => {
    try {
      const transaction = db.transaction([BACKUP_STORE_NAME], 'readwrite');
      const store = transaction.objectStore(BACKUP_STORE_NAME);
      
      const backup = {
        id: Security.generateSecureId('backup'),
        createdAt: Date.now(),
        state: {
          ads: state.ads,
          receipts: state.receipts,
          customers: state.customers,
          pages: state.pages,
          users: state.users.map(u => ({
            ...u,
            password: undefined,
            passwordHash: u.passwordHash,
            salt: u.salt,
            passwordAlgo: u.passwordAlgo,
            passwordIterations: u.passwordIterations
          })),
          settings: {
            defaultExchangeRate: state.defaultExchangeRate,
            exchangeRateHistory: state.exchangeRateHistory
          }
        },
        checksum: DataIntegrity.calculateChecksum(state)
      };
      
      const request = store.put(backup);
      request.onsuccess = () => {
        // Clean old backups
        cleanOldBackups();
        resolve(true);
      };
      request.onerror = () => resolve(false);
    } catch (error) {
      console.error('Error creating backup:', error);
      resolve(false);
    }
  });
}

async function cleanOldBackups() {
  if (!db) return;
  
  try {
    const cutoffDate = Date.now() - (STORAGE_CONFIG.BACKUP_RETENTION_DAYS * TIME_CONSTANTS.MILLISECONDS_PER_DAY);
    const transaction = db.transaction([BACKUP_STORE_NAME], 'readwrite');
    const store = transaction.objectStore(BACKUP_STORE_NAME);
    const index = store.index('createdAt');
    const range = IDBKeyRange.upperBound(cutoffDate);
    
    index.openCursor(range).onsuccess = (event) => {
      const cursor = event.target.result;
      if (cursor) {
        store.delete(cursor.primaryKey);
        cursor.continue();
      }
    };
  } catch (error) {
    console.error('Error cleaning old backups:', error);
  }
}

async function saveLogToIndexedDB(log) {
  if (!db) return false;
  
  return new Promise((resolve) => {
    try {
      const transaction = db.transaction([LOG_STORE_NAME], 'readwrite');
      const store = transaction.objectStore(LOG_STORE_NAME);
      const request = store.put(log);
      
      request.onsuccess = () => resolve(true);
      request.onerror = (e) => {
        console.error('Error saving log to IndexedDB:', e);
        resolve(false);
      };
    } catch (error) {
      console.error('IndexedDB transaction error:', error);
      resolve(false);
    }
  });
}

async function loadLogsFromIndexedDB() {
  if (!db) return [];
  
  return new Promise((resolve) => {
    try {
      const transaction = db.transaction([LOG_STORE_NAME], 'readonly');
      const store = transaction.objectStore(LOG_STORE_NAME);
      const request = store.getAll();
      
      request.onsuccess = () => {
        const logs = request.result || [];
        // Sort by date descending (handle invalid dates safely)
        logs.sort((a, b) => {
          const dateA = new Date(a.date || 0).getTime() || 0;
          const dateB = new Date(b.date || 0).getTime() || 0;
          return dateB - dateA;
        });
        resolve(logs);
      };
      
      request.onerror = (e) => {
        console.error('Error loading logs from IndexedDB:', e);
        resolve([]);
      };
    } catch (error) {
      console.error('IndexedDB load error:', error);
      resolve([]);
    }
  });
}

async function syncLogsToIndexedDB() {
  if (!db || !state.logs) return;
  
  const transaction = db.transaction([LOG_STORE_NAME], 'readwrite');
  const store = transaction.objectStore(LOG_STORE_NAME);
  
  for (const log of state.logs) {
    try {
      store.put(log);
    } catch (e) {
      console.error('Error syncing log:', e);
    }
  }
}

async function clearIndexedDBLogs() {
  if (!db) return;
  
  return new Promise((resolve) => {
    try {
      const transaction = db.transaction([LOG_STORE_NAME], 'readwrite');
      const store = transaction.objectStore(LOG_STORE_NAME);
      const request = store.clear();
      
      request.onsuccess = () => resolve(true);
      request.onerror = () => resolve(false);
    } catch (error) {
      resolve(false);
    }
  });
}
